function readSettings(): GlobalSettings { try { return { ...defaultSettings, ...JSON.parse(localStorage.getItem("edition-geek-global-settings") || "{}")} as GlobalSettings; } catch { return defaultSettings; } }
function money(value: number) { return value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }
function pricingMarginFraction(percent: number) { return percent >= 100 ? percent / (100 + percent) : percent / 100; }
function pricingMarginLabel(percent: number) { const effective = pricingMarginFraction(percent) * 100; return percent >= 100 ? `${percent}% (equivale a ${effective.toFixed(1)}% na fórmula)` : `${percent}%`; }

