function Index() {
  const [active, setActive] = useState("Dashboard");
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>(() => readSettings());
  const [menuOpen, setMenuOpen] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [toast, setToast] = useState("");

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2600); };
  const selectPage = (page: string) => { setActive(page); setMenuOpen(false); };
  const activeItem = navItems.find((item) => item.label === active);

  return <div className="print-app">
    <aside className={`sidebar ${menuOpen ? "is-open" : ""}`}>
      <div className="brand"><img className="brand-logo" src={logoUrl} alt="Edition Geek" /><div><strong>edition geek</strong><small>gestão para impressão</small></div><button className="sidebar-close" onClick={() => setMenuOpen(false)} aria-label="Fechar menu"><X size={19} /></button></div>
      <div className="workspace-switcher"><div className="workspace-avatar">EG</div><div><b>Edition Geek</b><span>Workspace principal</span></div><ChevronDown size={15} /></div>
      <nav className="side-nav">
        <p className="nav-label">MENU PRINCIPAL</p>
        {navItems.map(({ label, icon: Icon, group }) => <div key={label} className={group === "marketplaces" ? "nav-group-start" : ""}><button className={`nav-item ${active === label ? "active" : ""}`} onClick={() => selectPage(label)}><Icon size={17} /><span>{label}</span></button></div>)}
        <p className="nav-label nav-bottom">CONFIGURAÇÕES</p>
        <button className={`nav-item ${active === "Configurações" ? "active" : ""}`} onClick={() => selectPage("Configurações")}><Settings size={17} /><span>Configurações</span></button>
        <button className="nav-item" onClick={() => notify("Central de ajuda em breve")}><CircleHelp size={17} /><span>Central de ajuda</span></button>
      </nav>
      <div className="sidebar-user"><div className="user-avatar">J</div><div><b>julianaeditiongeek...</b><span>Juliana Edition Geek</span></div><ChevronRight size={15} /></div>
    </aside>
    <main className="main-content">
      <header className="topbar"><button className="mobile-menu" onClick={() => setMenuOpen(true)} aria-label="Abrir menu"><Menu size={22} /></button><div className="breadcrumb"><span>Edition Geek</span><b>/</b><strong>{activeItem?.label || active}</strong></div><div className="top-actions"><button className="icon-button" aria-label="Notificações" onClick={() => notify("Você não tem novas notificações")}><Bell size={18} /><i /></button><div className="profile"><div className="profile-avatar">J</div><div><b>Juliana</b><span>Administradora</span></div><ChevronDown size={15} /></div></div></header>
      <div className="page-wrap"><PageContent active={active} onAdd={() => setShowAdd(true)} onNotify={notify} settings={globalSettings} onSettingsChange={setGlobalSettings} /><footer className="footer-note"><span>© 2026 Edition Geek</span><span>Dados atualizados agora <i /></span></footer></div>
    </main>
    {showAdd && <PieceWizard settings={globalSettings} onClose={() => setShowAdd(false)} onSave={() => { setShowAdd(false); notify("Nova peça salva no histórico"); }} />}
    {toast && <div className="toast"><span>✓</span>{toast}</div>}
  </div>;
}

function PageContent({ active, onAdd, onNotify, settings, onSettingsChange }: { active: string; onAdd: () => void; onNotify: (message: string) => void; settings: GlobalSettings; onSettingsChange: (s: GlobalSettings) => void }) {
  if (active === "Dashboard") return <ManagementDashboard onAdd={onAdd} settings={settings} />;
  if (active === "Calculadora Filamento") return <FdmCalculator settings={settings} onNotify={onNotify} />;
  if (active === "Calculadora Resina + Pintura") return <ResinCalculator settings={settings} onNotify={onNotify} />;
  if (active === "Controle de Pedidos") return <OrdersPage onAdd={onAdd} />;
  if (active === "Histórico de Produtos") return <HistoryPage settings={settings} />;
  if (active === "Produtos") return <ProductsPage settings={settings} onAdd={onAdd} />;
  if (active === "Vitrine") return <VitrineAdminPage />;
  if (active === "Financeiro") return <FinancialPage />;
  if (active === "Recursos") return <ResourcesPage />;
  if (active === "Mercado Livre") return <StorePage />;
  if (active === "Usuários") return <UsersPage onAdd={onAdd} />;
  if (active === "Configurações") return <SettingsPage settings={settings} onSave={onSettingsChange} onNotify={onNotify} />;
  const config: Record<string, { icon: LucideIcon; subtitle: string; action: string; empty: string }> = {
    "Orçamentos": { icon: FileText, subtitle: "Crie propostas profissionais para seus clientes", action: "Novo orçamento", empty: "Nenhum orçamento encontrado" },
    "Análises": { icon: FileBarChart, subtitle: "Acompanhe os indicadores do seu negócio", action: "Exportar relatório", empty: "Nenhuma análise disponível" },
    "Clientes": { icon: UsersRound, subtitle: "Gerencie seus clientes e relacionamentos", action: "Novo cliente", empty: "Nenhum cliente cadastrado" },
    "Produtos": { icon: Gem, subtitle: "Organize seu catálogo de produtos", action: "Novo produto", empty: "Nenhum produto cadastrado" },
    "Melhor Envio": { icon: Truck, subtitle: "Gerencie suas entregas em um só lugar", action: "Configurar envio", empty: "Nenhuma entrega encontrada" },
  };
  const fallback = config["Clientes"]!;
  const pageConfig = config[active] || fallback;
  return <EmptyPage title={active} subtitle={pageConfig.subtitle} icon={pageConfig.icon} action={pageConfig.action} empty={pageConfig.empty} onAdd={onAdd} />;
}

function ManagementDashboard({ onAdd, settings }: { onAdd: () => void; settings: GlobalSettings }) {
  const products = readProductHistory(settings); const sold = products.filter((item) => item.chargedPrice > 0 && item.status !== "Cancelado"); const active = products.filter((item) => item.status === "À venda");
  const revenue = sold.reduce((sum, item) => sum + item.chargedPrice, 0); const costs = sold.reduce((sum, item) => sum + item.totalCost, 0); const profit = sold.reduce((sum, item) => sum + item.profit, 0); const weightedMargin = revenue ? profit / revenue * 100 : 0; const avgHour = sold.length ? sold.reduce((sum, item) => sum + item.effectiveHour, 0) / sold.length : 0; const target = activeLaborRate(settings);
  const loss = products.filter((item) => item.chargedPrice > 0 && item.margin < 0); const underpaid = products.filter((item) => item.workHours > 0 && item.effectiveHour < item.targetHour); const belowMarket = products.filter((item) => item.chargedPrice > 0 && item.announcedPrice > 0 && item.chargedPrice < item.announcedPrice);
  const complexities = ["Simples", "Intermediária", "Complexa-Premium"].map((name) => { const group = products.filter((item) => item.complexity === name && item.chargedPrice > 0); return { name, margin: group.length ? group.reduce((sum, item) => sum + item.margin, 0) / group.length : 0 }; });
  const categories = Array.from(new Set(sold.map((item) => item.category))).slice(0, 5).map((category) => ({ category, value: sold.filter((item) => item.category === category).length })); const categoryTotal = categories.reduce((sum, item) => sum + item.value, 0); let categoryCursor = 0; const categoryGradient = categories.map((item, index) => { const colors = ["#6B21A8", "#8b5ac3", "#F59E0B", "#47a985", "#8b9db9"]; const start = categoryTotal ? categoryCursor / categoryTotal * 100 : 0; categoryCursor += item.value; return `${colors[index % colors.length]} ${start}% ${categoryTotal ? categoryCursor / categoryTotal * 100 : 100}%`; }).join(", ");
  const typeStats = ["FDM", "Resina + Pintura"].map((type) => { const group = sold.filter((item) => item.type === type); return { type, cost: group.length ? group.reduce((sum, item) => sum + item.totalCost, 0) / group.length : 0, price: group.length ? group.reduce((sum, item) => sum + item.chargedPrice, 0) / group.length : 0 }; });
  return <section className="management-dashboard"><div className="page-heading compact-heading"><div><p className="eyebrow">VISÃO GERENCIAL · 20 DE AGOSTO DE 2026</p><h1>Olá, Juliana <span>👋</span></h1><p className="subtitle">Histórico, vendas e saúde operacional da Edition Geek em um só lugar.</p></div><button className="primary-button" onClick={onAdd}><Plus size={16} /> Novo pedido</button></div>
    <div className="management-kpis history-kpis"><DashboardKpi icon={Package} label="Peças produzidas" value={String(products.length)} change={`${sold.length} vendidas`} tone="neutral" /><DashboardKpi icon={CircleDollarSign} label="Faturamento acumulado" value={money(revenue)} change="vendas registradas" tone="positive" /><DashboardKpi icon={Boxes} label="Custo acumulado" value={money(costs)} change="produtos vendidos" tone="neutral" /><DashboardKpi icon={TrendingUp} label="Lucro acumulado" value={money(profit)} change={`${weightedMargin.toFixed(1)}% margem ponderada`} tone={profit >= 0 ? "positive" : "neutral"} /><DashboardKpi icon={Percent} label="Margem média ponderada" value={`${weightedMargin.toFixed(1)}%`} change="sobre vendas" tone="positive" /><DashboardKpi icon={UserCog} label="Valor/h Fábio" value={`${money(avgHour)}/h`} change={`meta ${money(target)}/h`} tone={avgHour >= target ? "positive" : "neutral"} /></div>
    <div className="management-alerts"><DashboardAlert title="Peças com prejuízo" count={loss.length} items={loss} tone="danger" /><DashboardAlert title="Abaixo do valor/hora alvo" count={underpaid.length} items={underpaid} tone="warning" /><DashboardAlert title="Abaixo do preço de mercado" count={belowMarket.length} items={belowMarket} tone="warning" /></div>
    <div className="dashboard-main-grid"><div className="panel production-card stock-card"><div className="dashboard-card-head"><div><h2>Peças à venda</h2><p>Estoque pronto ainda não vendido</p></div><strong className="stock-total">{money(active.reduce((sum, item) => sum + item.announcedPrice, 0))}</strong></div><div className="stock-summary"><b>{active.length}</b><span>peças prontas · valor total anunciado</span></div><div className="recent-sale-list">{active.slice(0, 4).map((item) => <div className="recent-sale" key={item.id}><span className="sale-avatar"><Package size={14} /></span><div><b>{item.name}</b><small>{item.channel} · {item.completedAt}</small></div><div className="sale-value"><strong>{money(item.announcedPrice)}</strong><em className="making">À venda</em></div></div>)}</div></div><div className="panel dashboard-chart-card"><div className="dashboard-card-head"><div><h2>Margem por complexidade</h2><p>Média das peças vendidas</p></div><TrendingUp size={16} color="var(--accent)" /></div><div className="complexity-bars">{complexities.map((item) => <div className="complexity-bar-row" key={item.name}><span>{item.name}</span><div><i style={{ width: `${Math.min(100, Math.max(4, item.margin))}%` }} /></div><b>{item.margin.toFixed(1)}%</b></div>)}</div><div className="dashboard-note">Quanto maior a complexidade, maior a necessidade de acompanhar o valor/hora.</div></div></div>
    <div className="dashboard-bottom-grid"><div className="panel dashboard-chart-card"><div className="dashboard-card-head"><div><h2>Valor/hora efetivo ao longo do tempo</h2><p>Comparação com a meta de {money(target)}/h</p></div><Clock3 size={16} color="var(--accent)" /></div><div className="hour-line-chart"><div className="hour-line-target" /><svg viewBox="0 0 500 150" preserveAspectRatio="none"><polyline points={sold.slice(-8).map((item, index) => `${index * (500 / Math.max(1, sold.slice(-8).length - 1))},${Math.max(8, 140 - Math.min(130, item.effectiveHour / Math.max(target, 1) * 70))}`).join(" ")} fill="none" stroke="#6B21A8" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" /></svg><small className="hour-target-label">Meta {money(target)}/h</small></div></div><div className="panel dashboard-chart-card"><div className="dashboard-card-head"><div><h2>Mix de categorias vendidas</h2><p>Distribuição por quantidade</p></div><PieChart size={16} color="var(--accent)" /></div><div className="management-donut-wrap"><div className="management-donut" style={{ background: `conic-gradient(${categoryGradient || "#eee 0 100%"})` }}><div>{sold.length}<small>vendas</small></div></div><div className="breakdown-legend">{categories.map((item, index) => <div key={item.category}><i style={{ background: ["#6B21A8", "#8b5ac3", "#F59E0B", "#47a985", "#8b9db9"][index % 5] }} /><span>{item.category}</span><b>{item.value}</b></div>)}</div></div></div></div>
    <div className="panel dashboard-chart-card type-comparison"><div className="dashboard-card-head"><div><h2>Custo vs. preço médio por tipo</h2><p>Comparação entre FDM e Resina + Pintura</p></div><FileBarChart size={16} color="var(--accent)" /></div><div className="type-bars">{typeStats.map((item) => <div className="type-bar-group" key={item.type}><b>{item.type}</b><div className="type-bar-line"><span>Custo</span><i className="cost" style={{ width: `${item.price ? item.cost / item.price * 100 : 4}%` }} /><strong>{money(item.cost)}</strong></div><div className="type-bar-line"><span>Preço</span><i className="price" style={{ width: `${item.price ? 100 : 4}%` }} /><strong>{money(item.price)}</strong></div></div>)}</div></div>
  </section>;
}

function DashboardAlert({ title, count, items, tone }: { title: string; count: number; items: HistoryProduct[]; tone: "danger" | "warning" }) { return <div className={`dashboard-alert ${tone}`}><span>{tone === "danger" ? <AlertTriangle size={15} /> : <Info size={15} />}</span><div><b>{title}</b><strong>{count}</strong><small>{items.slice(0, 2).map((item) => item.name).join(" · ") || "Nenhuma ocorrência"}</small></div></div>; }

function ProductsPage({ settings, onAdd }: { settings: GlobalSettings; onAdd: () => void }) {
  const [query, setQuery] = useState(""); const [type, setType] = useState("Todos"); const [status, setStatus] = useState("Todos"); const [complexity, setComplexity] = useState("Todas"); const [view, setView] = useState("Todos");
  const [overrides, setOverrides] = useState<Record<string, ProductStatus>>(() => { try { return JSON.parse(localStorage.getItem("edition-geek-product-status-overrides") || "{}"); } catch { return {}; } });
  const [excluded, setExcluded] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem("edition-geek-product-exclusions") || "[]"); } catch { return []; } });
  const allProducts = readProductHistory(settings).filter((item) => !excluded.includes(item.id)).map((item) => ({ ...item, status: overrides[item.id] || (item.status === "À venda" ? "Disponível" : item.status) }));
  const readyProducts = allProducts.filter((item) => item.status === "Disponível");
  const products = allProducts.filter((item) => item.name.toLowerCase().includes(query.toLowerCase()) && (type === "Todos" || item.type === type) && (status === "Todos" || item.status === status) && (complexity === "Todas" || item.complexity === complexity) && (view === "Todos" || item.status === view));
  const updateStatus = (id: string, nextStatus: ProductStatus) => { const next = { ...overrides, [id]: nextStatus }; setOverrides(next); localStorage.setItem("edition-geek-product-status-overrides", JSON.stringify(next)); };
  const deleteProduct = (id: string) => { if (!window.confirm("Excluir este produto da aba Produtos?")) return; const next = [...excluded, id]; setExcluded(next); localStorage.setItem("edition-geek-product-exclusions", JSON.stringify(next)); };
  const statusClass = (value: ProductStatus) => value === "Vendido" || value === "Entregue" ? "sold" : value === "Disponível" ? "stock" : value === "Cancelado" ? "cancelled" : "quoted";
  return <section className="content-page products-page"><div className="page-heading section-heading"><div><h1><Gem size={21} /> Produtos</h1><p className="subtitle">Pesquise, acompanhe o status e consulte todas as peças da Edition Geek.</p></div><button className="primary-button" onClick={onAdd}><Plus size={15} /> Nova peça</button></div>
    <div className="history-summary"><div><b>{products.length}</b><span>produtos encontrados</span></div><div><b>{readyProducts.length}</b><span>pronta entrega</span></div><div><b>{money(readyProducts.reduce((sum, item) => sum + (item.announcedPrice || item.chargedPrice || 0), 0))}</b><span>valor em estoque</span></div></div>
    <div className="products-view-tabs"><button className={view === "Todos" ? "selected" : ""} onClick={() => setView("Todos")}>Todos ({allProducts.length})</button><button className={view === "Disponível" ? "selected" : ""} onClick={() => setView("Disponível")}>Pronta entrega ({readyProducts.length})</button><button className={view === "Vendido" ? "selected" : ""} onClick={() => setView("Vendido")}>Vendidos ({allProducts.filter((item) => item.status === "Vendido").length})</button><button className={view === "Em produção" ? "selected" : ""} onClick={() => setView("Em produção")}>Em produção ({allProducts.filter((item) => item.status === "Em produção").length})</button></div>
    <div className="panel history-filter-panel products-filter"><div className="search-box history-search"><Search size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Pesquisar produto pelo nome..." /></div><select value={type} onChange={(event) => setType(event.target.value)}><option>Todos</option><option>FDM</option><option>Resina + Pintura</option></select><select value={status} onChange={(event) => setStatus(event.target.value)}><option>Todos</option>{productStatuses.map((item) => <option key={item}>{item}</option>)}</select><select value={complexity} onChange={(event) => setComplexity(event.target.value)}><option>Todas</option><option>Simples</option><option>Intermediária</option><option>Complexa-Premium</option></select></div>
    <div className="panel products-table"><div className="products-table-head"><span>PRODUTO</span><span>TIPO</span><span>CATEGORIA</span><span>HORAS FÁBIO</span><span>CUSTO TOTAL</span><span>PREÇO COBRADO</span><span>MARGEM</span><span>STATUS</span><span>AÇÕES</span></div>{products.map((item) => <div className={"products-table-row " + (item.margin < 0 ? "history-negative" : item.workHours > 0 && item.effectiveHour < item.targetHour ? "history-below-target" : "")} key={item.id}><div className="history-name"><b>{item.name}</b><small>{item.completedAt}</small></div><span><em className={"type-pill " + (item.type === "FDM" ? "fdm" : "resin")}>{item.type === "FDM" ? "FDM" : "Resina"}</em></span><span>{item.category}<small>{item.complexity}</small></span><span>{item.workHours.toFixed(2)} h</span><span>{money(item.totalCost)}</span><span>{item.chargedPrice ? money(item.chargedPrice) : "A definir"}</span><span className={item.margin < 0 ? "negative-text" : "positive-text"}>{item.chargedPrice ? item.margin.toFixed(1) + "%" : "—"}</span><span><select aria-label={"Status de " + item.name} className={"product-status-select " + statusClass(item.status)} value={item.status} onChange={(event) => updateStatus(item.id, event.target.value as ProductStatus)}>{productStatuses.map((option) => <option key={option} value={option}>{option}</option>)}</select></span><span><button className="product-delete-button" onClick={() => deleteProduct(item.id)} aria-label={"Excluir " + item.name}><Trash2 size={14} /></button></span></div>)}</div>
  </section>;
}
function HistoryPage({ settings }: { settings: GlobalSettings }) {
  const [query, setQuery] = useState(""); const [type, setType] = useState("Todos"); const [category, setCategory] = useState("Todas"); const [status, setStatus] = useState("Todos"); const [complexity, setComplexity] = useState("Todas"); const [period, setPeriod] = useState("Todos"); const [sort, setSort] = useState<keyof HistoryProduct>("completedAt"); const [direction, setDirection] = useState<"asc" | "desc">("desc"); const [selected, setSelected] = useState<HistoryProduct | null>(null);
  const products = readProductHistory(settings); const categories = Array.from(new Set(products.map((item) => item.category))).filter(Boolean);
  const filtered = products.filter((item) => item.name.toLowerCase().includes(query.toLowerCase()) && (type === "Todos" || item.type === type) && (category === "Todas" || item.category === category) && (status === "Todos" || item.status === status) && (complexity === "Todas" || item.complexity === complexity) && (period === "Todos" || item.completedAt.includes(period))).sort((a, b) => { const left = a[sort]; const right = b[sort]; const value = typeof left === "number" && typeof right === "number" ? left - right : String(left).localeCompare(String(right)); return direction === "asc" ? value : -value; });
  const setSortBy = (column: keyof HistoryProduct) => { if (sort === column) setDirection((value) => value === "asc" ? "desc" : "asc"); else { setSort(column); setDirection("asc"); } };
  const exportCsv = () => { const header = ["Nome", "Tipo", "Categoria", "Complexidade", "Horas Fábio", "Custo total", "Preço cobrado", "Canal", "Margem real %", "Lucro real", "Valor/h efetivo", "Status", "Data conclusão", "Observações"]; const rows = filtered.map((item) => [item.name, item.type, item.category, item.complexity, item.workHours.toFixed(2), item.totalCost.toFixed(2), item.chargedPrice.toFixed(2), item.channel, item.margin.toFixed(2), item.profit.toFixed(2), item.effectiveHour.toFixed(2), item.status, item.completedAt, item.notes].map((value) => `"${String(value).replace(/"/g, '""')}"`).join(",")); const blob = new Blob(["\uFEFF" + [header.join(","), ...rows].join("\n")], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "historico-produtos-edition-geek.csv"; link.click(); URL.revokeObjectURL(url); };
  return <section className="content-page history-page"><div className="page-heading section-heading"><div><h1><ClipboardList size={21} /> Histórico de Produtos</h1><p className="subtitle">Todos os produtos finalizados, custos e resultados reais de venda.</p></div><button className="primary-button" onClick={exportCsv}><Receipt size={15} /> Exportar CSV</button></div><div className="history-summary"><div><b>{filtered.length}</b><span>produtos encontrados</span></div><div><b>{money(filtered.reduce((sum, item) => sum + item.chargedPrice, 0))}</b><span>faturamento filtrado</span></div><div><b>{money(filtered.reduce((sum, item) => sum + item.profit, 0))}</b><span>lucro filtrado</span></div></div><div className="panel history-filter-panel"><div className="search-box history-search"><Search size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por nome..." /></div><select value={type} onChange={(event) => setType(event.target.value)}><option>Todos</option><option>FDM</option><option>Resina + Pintura</option></select><select value={category} onChange={(event) => setCategory(event.target.value)}><option>Todas</option>{categories.map((item) => <option key={item}>{item}</option>)}</select><select value={complexity} onChange={(event) => setComplexity(event.target.value)}><option>Todas</option><option>Simples</option><option>Intermediária</option><option>Complexa-Premium</option></select><select value={status} onChange={(event) => setStatus(event.target.value)}><option>Todos</option><option>À venda</option><option>Vendido</option><option>Cancelado</option></select><select value={period} onChange={(event) => setPeriod(event.target.value)}><option>Todos</option><option>2026</option><option>2025</option></select></div><div className="panel history-table-panel"><div className="history-grid-row history-grid-head"><HistoryHeader label="PRODUTO" column="name" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="TIPO" column="type" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="CATEGORIA" column="category" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="HORAS FÁBIO" column="workHours" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="CUSTO TOTAL" column="totalCost" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="PREÇO COBRADO" column="chargedPrice" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="MARGEM" column="margin" sort={sort} direction={direction} onSort={setSortBy} /><HistoryHeader label="VALOR/H" column="effectiveHour" sort={sort} direction={direction} onSort={setSortBy} /><span>STATUS</span><span /></div>{filtered.map((item) => <div className={`history-grid-row history-data-row ${item.margin < 0 ? "history-negative" : item.workHours > 0 && item.effectiveHour < item.targetHour ? "history-below-target" : ""}`} key={item.id}><div className="history-name"><b>{item.name}</b><small>{item.completedAt}</small></div><span><em className={`type-pill ${item.type === "FDM" ? "fdm" : "resin"}`}>{item.type === "FDM" ? "FDM" : "Resina"}</em></span><span>{item.category}<small>{item.complexity}</small></span><span>{item.workHours.toFixed(2)} h</span><span>{money(item.totalCost)}</span><span>{item.chargedPrice ? money(item.chargedPrice) : "A definir"}</span><span className={item.margin < 0 ? "negative-text" : ""}>{item.chargedPrice ? `${item.margin.toFixed(1)}%` : "—"}</span><span className={item.effectiveHour < item.targetHour ? "negative-text" : "positive-text"}>{item.effectiveHour ? `${money(item.effectiveHour)}/h` : "—"}</span><span><em className={`status-pill ${item.status === "Vendido" ? "sold" : item.status === "À venda" ? "stock" : "cancelled"}`}>{item.status}</em></span><button className="row-view-button" onClick={() => setSelected(item)}>Ver ficha</button></div>)}</div><div className="panel complexity-analysis"><div className="dashboard-card-head"><div><h2>Análise por complexidade</h2><p>Médias calculadas sobre os produtos do histórico.</p></div><TrendingUp size={16} color="var(--accent)" /></div><div className="complexity-analysis-table"><div className="complexity-analysis-row complexity-analysis-head"><span>COMPLEXIDADE</span><span>QTD</span><span>MÉDIA HORAS</span><span>MÍN / MÁX HORAS</span><span>MÉDIA CUSTO</span><span>MÉDIA PREÇO</span><span>MÉDIA MARGEM</span><span>MÉDIA VALOR/H</span></div>{["Simples", "Intermediária", "Complexa-Premium"].map((name) => { const group = filtered.filter((item) => item.complexity === name); const hours = group.map((item) => item.workHours); const soldGroup = group.filter((item) => item.chargedPrice > 0); return <div className="complexity-analysis-row" key={name}><b>{name}</b><span>{group.length}</span><span>{group.length ? (hours.reduce((sum, value) => sum + value, 0) / group.length).toFixed(2) : "—"} h</span><span>{hours.length ? `${Math.min(...hours).toFixed(2)} / ${Math.max(...hours).toFixed(2)} h` : "—"}</span><span>{group.length ? money(group.reduce((sum, item) => sum + item.totalCost, 0) / group.length) : "—"}</span><span>{soldGroup.length ? money(soldGroup.reduce((sum, item) => sum + item.chargedPrice, 0) / soldGroup.length) : "—"}</span><span>{soldGroup.length ? `${(soldGroup.reduce((sum, item) => sum + item.margin, 0) / soldGroup.length).toFixed(1)}%` : "—"}</span><span>{soldGroup.length ? `${money(soldGroup.reduce((sum, item) => sum + item.effectiveHour, 0) / soldGroup.length)}/h` : "—"}</span></div>; })}</div></div>{selected && <div className="modal-backdrop" onMouseDown={() => setSelected(null)}><div className="modal history-detail-modal" onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">FICHA COMPLETA</p><h2>{selected.name}</h2></div><button className="close-button" onClick={() => setSelected(null)}><X size={18} /></button></div><div className="detail-badges"><span>{selected.type}</span><span>{selected.category}</span><span>{selected.status}</span></div><div className="detail-metrics"><Metric label="Custo total" value={money(selected.totalCost)} /><Metric label="Preço cobrado" value={selected.chargedPrice ? money(selected.chargedPrice) : "A definir"} /><Metric label="Lucro real" value={money(selected.profit)} /><Metric label="Valor/h efetivo" value={selected.effectiveHour ? `${money(selected.effectiveHour)}/h` : "—"} /></div><p className="detail-note">{selected.notes || "Sem observações registradas."}</p>{selected.detail && <pre className="detail-json">{JSON.stringify(selected.detail, null, 2)}</pre>}</div></div>}</section>;
}

function HistoryHeader({ label, column, sort, direction, onSort }: { label: string; column: keyof HistoryProduct; sort: keyof HistoryProduct; direction: "asc" | "desc"; onSort: (column: keyof HistoryProduct) => void }) { return <button className="history-sort-button" onClick={() => onSort(column)}>{label}{sort === column && <span>{direction === "asc" ? "↑" : "↓"}</span>}</button>; }

function Dashboard({ onAdd }: { onAdd: () => void }) {
  const [period, setPeriod] = useState("Este mês");
  const sales = period === "Este mês" ? [42, 58, 47, 74, 62, 89, 78, 92, 84, 106, 98, 124] : period === "Últimos 30 dias" ? [31, 48, 39, 68, 57, 79, 70, 86, 76, 93, 88, 114] : [25, 42, 35, 55, 49, 64, 58, 71, 65, 82, 75, 99];
  const maxSale = Math.max(...sales);
  const production = [{ label: "Em impressão", count: 8, color: "purple", detail: "3 FDM · 5 resina" }, { label: "Aguardando acabamento", count: 5, color: "orange", detail: "Pintura e montagem" }, { label: "Prontos para envio", count: 12, color: "green", detail: "Pedidos finalizados" }];
  const products = [{ name: "Cubo Infinito", sales: 18, revenue: "R$ 1.260,00", color: "#6127aa" }, { name: "Batmóvel", sales: 11, revenue: "R$ 1.210,00", color: "#8b5ac3" }, { name: "Angry Birds Red", sales: 9, revenue: "R$ 315,00", color: "#b99bdd" }, { name: "Shelby Cobra", sales: 6, revenue: "R$ 900,00", color: "#d6c3ed" }];
  return <section className="management-dashboard">
    <div className="page-heading compact-heading"><div><p className="eyebrow">VISÃO GERAL · 09 DE AGOSTO DE 2026</p><h1>Olá, Juliana <span>👋</span></h1><p className="subtitle">Acompanhe a operação, as vendas e a capacidade da Edition Geek.</p></div><button className="primary-button" onClick={onAdd}><Plus size={16} /> Novo pedido</button></div>
    <div className="dashboard-toolbar"><div><b>Resumo gerencial</b><span>Indicadores atualizados agora</span></div><div className="period-switcher">{["Este mês", "Últimos 30 dias", "Este ano"].map((item) => <button key={item} className={period === item ? "selected" : ""} onClick={() => setPeriod(item)}>{item}</button>)}</div></div>
    <div className="management-kpis"><DashboardKpi icon={CircleDollarSign} label="Vendas no período" value="R$ 8.420,00" change="+18,4%" tone="positive" /><DashboardKpi icon={TrendingUp} label="Lucro estimado" value="R$ 3.186,00" change="37,8% margem" tone="positive" /><DashboardKpi icon={Package} label="Pedidos em andamento" value="25" change="8 em impressão" tone="neutral" /><DashboardKpi icon={Clock3} label="Capacidade utilizada" value="76%" change="3 impressoras ativas" tone="neutral" /></div>
    <div className="dashboard-main-grid"><div className="panel dashboard-chart-card"><div className="dashboard-card-head"><div><h2>Vendas ao longo do tempo</h2><p>Receita bruta por período</p></div><span className="chart-legend"><i /> Receita</span></div><div className="sales-chart"><div className="chart-y-axis"><span>R$ 150</span><span>R$ 100</span><span>R$ 50</span><span>R$ 0</span></div><div className="chart-plot">{["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"].map((month, index) => { const sale = sales[index] ?? 0; return <div className="chart-column" key={month}><div className="chart-bar" style={{ height: `${Math.max(8, sale / maxSale * 100)}%` }}><span>{sale}</span></div><small>{month}</small></div>; })}</div></div><div className="chart-summary"><strong>R$ 8.420,00</strong><span>+18,4% em relação ao período anterior</span></div></div><div className="panel production-card"><div className="dashboard-card-head"><div><h2>Produção agora</h2><p>Status dos pedidos em aberto</p></div><button className="text-button">Ver pedidos <ArrowRight size={13} /></button></div><div className="production-list">{production.map((item) => <div className="production-item" key={item.label}><span className={`production-icon ${item.color}`}>{item.color === "green" ? <CheckCircle2 size={16} /> : item.color === "orange" ? <Clock3 size={16} /> : <Printer size={16} />}</span><div><b>{item.label}</b><small>{item.detail}</small></div><strong>{item.count}</strong></div>)}</div><div className="capacity-box"><div><span>Capacidade das máquinas</span><b>76%</b></div><div className="capacity-track"><i /></div><small>Impressoras A1, Mars 5 e Saturn 4</small></div></div></div>
    <div className="dashboard-bottom-grid"><div className="panel product-ranking"><div className="dashboard-card-head"><div><h2>Produtos mais vendidos</h2><p>Desempenho acumulado no período</p></div><button className="text-button">Ver produtos <ArrowRight size={13} /></button></div><div className="ranking-list">{products.map((product, index) => <div className="ranking-row" key={product.name}><span className="ranking-position">{index + 1}</span><div className="ranking-product"><b>{product.name}</b><div className="ranking-track"><i style={{ width: `${product.sales / 18 * 100}%`, background: product.color }} /></div></div><span>{product.sales} vendas</span><strong>{product.revenue}</strong></div>)}</div></div><div className="panel recent-sales"><div className="dashboard-card-head"><div><h2>Últimas vendas</h2><p>Pedidos recebidos recentemente</p></div><button className="text-button">Ver todas <ArrowRight size={13} /></button></div><div className="recent-sale-list"><RecentSale name="Cubo Infinito" customer="Mariana Geek · há 12 min" value="R$ 70,00" status="Pago" /><RecentSale name="Batmóvel" customer="Carlos Lima · há 48 min" value="R$ 110,00" status="Em produção" /><RecentSale name="Angry Birds Red" customer="Ana Souza · há 2 h" value="R$ 35,00" status="Pago" /></div></div></div>
  </section>;
}

function DashboardKpi({ icon: Icon, label, value, change, tone }: { icon: LucideIcon; label: string; value: string; change: string; tone: "positive" | "neutral" }) { return <div className="management-kpi"><span className={`kpi-icon ${tone}`}><Icon size={17} /></span><div><small>{label}</small><strong>{value}</strong><em className={tone}>{change}</em></div></div>; }
function RecentSale({ name, customer, value, status }: { name: string; customer: string; value: string; status: string }) { return <div className="recent-sale"><span className="sale-avatar"><Package size={14} /></span><div><b>{name}</b><small>{customer}</small></div><div className="sale-value"><strong>{value}</strong><em className={status === "Pago" ? "paid" : "making"}>{status}</em></div></div>; }

function ResinCalculator({ settings, onNotify }: { settings: GlobalSettings; onNotify: (message: string) => void }) {
  const globalConsumable = (name: string, fallback: number) => settings.consumables.find((item) => item.name.toLowerCase().includes(name.toLowerCase()))?.cost ?? fallback;
  const initial = () => { const base = emptyResinForm(); return { ...base, ipa: globalConsumable("álcool", base.ipa), gloves: globalConsumable("luvas", base.gloves), sandpaper: globalConsumable("lixas", base.sandpaper), primer: globalConsumable("primer", base.primer), paints: globalConsumable("tintas", base.paints), airbrush: globalConsumable("aerógrafo", base.airbrush), varnishCost: globalConsumable("verniz", base.varnishCost), glue: globalConsumable("cola", base.glue), otherConsumable: globalConsumable("outros", base.otherConsumable) }; };
  const [form, setForm] = useState<ResinForm>(() => initial());
  const [history, setHistory] = useState<ResinHistoryItem[]>(() => { try { return JSON.parse(localStorage.getItem("edition-geek-resin-history") || "null") || initialResinHistory; } catch { return initialResinHistory; } });
  const [showHistory, setShowHistory] = useState(false); const [search, setSearch] = useState("");
  const printTime = form.printHours + form.printMinutes / 60;
  const manualHours = [form.cleaning, form.sanding, form.primerBase, form.painting, form.varnish, form.assembly].reduce((sum, value) => sum + timeToHours(value), 0);
  const selectedChannel = settings.channels.find((channel) => channel.name === form.channelName) || settings.channels[0] || { name: "Pix", commission: 0, fixedFee: 0, note: "—" };
  const selectedPackage = settings.packages.find((item) => item.name === form.packageName);
  const resinCost = form.volumeMl / 1000 * form.resinLiter * (1 + settings.resinLoss / 100);
  const energyCost = printTime * settings.resinPower * settings.resinKwh;
  const depreciation = printTime * (settings.resinPurchase / settings.resinLife);
  const printing = resinCost + energyCost + depreciation;
  const laborRate = activeLaborRate(settings); const indirectRate = activeIndirectRate(settings);
  const labor = manualHours * laborRate; const indirect = manualHours * indirectRate;
  const consumables = form.ipa + form.gloves + form.sandpaper + form.primer + form.paints + form.airbrush + form.varnishCost + form.glue + form.otherConsumable;
  const components = form.support + form.led + form.pedestal + (selectedPackage?.cost || 0) + form.otherComponent;
  const total = printing + labor + consumables + components + indirect;
  const commission = (selectedChannel.commission || 0) / 100; const tax = settings.salesTax / 100;
  const minBase = 1 - commission - tax; const recommendedBase = 1 - pricingMarginFraction(settings.defaultMargin) - commission - tax;
  const minimum = minBase > 0 ? total / minBase : 0; const recommended = recommendedBase > 0 ? total / recommendedBase : 0; const eventPrice = recommended * (1 + settings.eventAdditional / 100);
  const adjusted = form.adjustedPrice || recommended; const channelFees = adjusted * commission + (selectedChannel.fixedFee || 0); const realProfit = adjusted - total - channelFees; const realMargin = adjusted > 0 ? (adjusted - total) / adjusted * 100 : 0; const effectiveHour = manualHours > 0 ? realProfit / manualHours : 0;
  const update = (key: keyof ResinForm, value: string | number) => setForm((current) => ({ ...current, [key]: value }));
  const costs = { printing, labor, consumables, components, indirect, total, suggested: recommended, adjusted };
  const saveHistory = () => { const item: ResinHistoryItem = { ...form, id: `${Date.now()}`, savedAt: new Date().toLocaleString("pt-BR"), costs }; const next = [item, ...history]; setHistory(next); localStorage.setItem("edition-geek-resin-history", JSON.stringify(next)); onNotify("Ficha de resina salva no histórico"); };
  const loadItem = (item: ResinHistoryItem, duplicate = false) => { const { id: _id, costs: _costs, savedAt: _savedAt, ...formValues } = item; setForm({ ...formValues, name: duplicate ? `${item.name} · cópia` : item.name }); setShowHistory(false); };
  const importCsv = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const lines = String(reader.result || "").split(/\r?\n/).filter(Boolean); if (lines.length < 2) return; const headers = parseCsvLine(lines[0] || "").map((header) => header.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")); const imported = lines.slice(1).map((line, index) => { const values = parseCsvLine(line); const value = (names: string[]) => { const position = headers.findIndex((header) => names.some((name) => header.includes(name))); return position >= 0 ? values[position] || "" : ""; }; const number = (names: string[]) => Number(value(names).replace(",", ".")) || 0; return { ...emptyResinForm(), id: `resin-csv-${Date.now()}-${index}`, name: value(["nome", "produto"]) || `Produto importado ${index + 1}`, volumeMl: number(["volume", "gramas", "resina"]), adjustedPrice: number(["venda ajustada", "ajustado"]), savedAt: "Importado via CSV", costs: { printing: number(["custo impressao", "custo de impressao"]), labor: number(["custo mao", "custo pintura", "custo servico"]), consumables: number(["consumiveis"]), components: number(["componentes"]), indirect: 0, total: number(["custo total"]), suggested: number(["sugerido", "valor venda"]), adjusted: number(["venda ajustada", "ajustado"]) } }; }); const next = [...imported, ...history]; setHistory(next); localStorage.setItem("edition-geek-resin-history", JSON.stringify(next)); onNotify(`${imported.length} produto(s) de resina importado(s)`); }; reader.readAsText(file, "UTF-8"); event.target.value = ""; };
  const breakdown = [{ label: "Impressão", value: printing, color: "#6127aa" }, { label: "Mão de obra", value: labor, color: "#db8c45" }, { label: "Consumíveis", value: consumables, color: "#47a985" }, { label: "Componentes", value: components, color: "#8b9db9" }, { label: "Overhead", value: indirect, color: "#c5a2df" }]; const breakdownTotal = breakdown.reduce((sum, item) => sum + item.value, 0); let cursor = 0; const gradient = breakdown.map((item) => { const start = breakdownTotal ? cursor / breakdownTotal * 100 : 0; cursor += item.value; const end = breakdownTotal ? cursor / breakdownTotal * 100 : 0; return `${item.color} ${start}% ${end}%`; }).join(", ");
  const alertLoss = adjusted > 0 && adjusted < minimum; const alertLabor = manualHours > 0 && effectiveHour < laborRate; const alertMarket = form.marketPrice > 0 && minimum > form.marketPrice; const alertPaint = timeToHours(form.painting) > 0 && form.paints <= 0;
  return <PageFrame icon={Paintbrush} title="Calculadora Resina + Pintura" subtitle="Custo e preço de peças em ABS-Like com pós-processamento manual" action="Novo produto" onAction={() => setForm(initial())}>
    <div className="fdm-toolbar resin-toolbar"><div className="fdm-context"><Droplets size={15} /><span>Parâmetros globais ativos · resina {money(settings.resinPrice)}/L · Fábio {money(laborRate)}/h</span></div><div className="fdm-actions"><button className="secondary-button" onClick={() => setShowHistory((value) => !value)}><ClipboardList size={13} /> Histórico ({history.length})</button><label className="secondary-button file-button"><Tags size={13} /> Importar CSV<input type="file" accept=".csv,.tsv" onChange={importCsv} /></label><button className="secondary-button" onClick={() => window.print()}><Receipt size={13} /> Exportar PDF</button></div></div>
    <div className="fdm-layout resin-layout"><div className="fdm-form-column">
      <FdmCard title="Identificação do produto" icon={Gem}><div className="form-grid two"><FdmInput label="Nome do produto / projeto" value={form.name} onChange={(value) => update("name", value)} placeholder="Ex: Estátua personalizada" /><FdmSelect label="Categoria" value={form.category} options={["Estátua", "Colecionável", "Decoração", "Busto", "Anime", "Games", "Personalizado", "Outro"]} onChange={(value) => update("category", value)} /><FdmSelect label="Status" value={form.status} options={["Em produção", "Pronto", "Vendido", "Cancelado"]} onChange={(value) => update("status", value)} /><FdmSelect label="Complexidade" value={form.complexity} options={["Simples", "Intermediária", "Complexa-Premium"]} onChange={(value) => update("complexity", value)} /></div></FdmCard>
      <FdmCard title="Parâmetros de impressão resina" icon={Droplets}><div className="form-grid three"><FdmSelect label="Impressora usada" value={form.printer} options={["Elegoo Mars 5 Ultra", "Elegoo Saturn 4 Ultra"]} onChange={(value) => update("printer", value)} /><FdmInput label="Custo da resina (R$/L)" type="number" value={form.resinLiter} onChange={(value) => update("resinLiter", Number(value))} /><FdmInput label="Volume gasto (ml)" type="number" value={form.volumeMl} onChange={(value) => update("volumeMl", Number(value))} /><div className="fdm-time-group"><span>Tempo de impressão</span><div><FdmInput label="Horas" type="number" value={form.printHours} onChange={(value) => update("printHours", Number(value))} /><FdmInput label="Minutos" type="number" value={form.printMinutes} onChange={(value) => update("printMinutes", Number(value))} /></div></div></div></FdmCard>
      <FdmCard title="Pós-processamento e pintura" icon={Paintbrush}><p className="fdm-helper">Conte somente as horas efetivas de trabalho manual do Fábio.</p><div className="form-grid three"><FdmInput label="Limpeza / lavagem (hh:mm)" value={form.cleaning} onChange={(value) => update("cleaning", value)} placeholder="00:00" /><FdmInput label="Lixamento / preparação (hh:mm)" value={form.sanding} onChange={(value) => update("sanding", value)} placeholder="00:00" /><FdmInput label="Primer e base (hh:mm)" value={form.primerBase} onChange={(value) => update("primerBase", value)} placeholder="00:00" /><FdmInput label="Pintura (hh:mm)" value={form.painting} onChange={(value) => update("painting", value)} placeholder="00:00" /><FdmInput label="Verniz e acabamento (hh:mm)" value={form.varnish} onChange={(value) => update("varnish", value)} placeholder="00:00" /><FdmInput label="Montagem / colagem (hh:mm)" value={form.assembly} onChange={(value) => update("assembly", value)} placeholder="00:00" /></div><div className="fdm-total-line"><span>Total de horas de trabalho manual</span><strong>{formatHours(manualHours)} · {manualHours.toFixed(2)} h</strong></div></FdmCard>
      <FdmCard title="Consumíveis de pintura nesta peça" icon={Boxes}><div className="form-grid three resin-consumable-grid"><FdmInput label="Álcool IPA (R$)" type="number" value={form.ipa} onChange={(value) => update("ipa", Number(value))} /><FdmInput label="Luvas (R$)" type="number" value={form.gloves} onChange={(value) => update("gloves", Number(value))} /><FdmInput label="Lixas (R$)" type="number" value={form.sandpaper} onChange={(value) => update("sandpaper", Number(value))} /><FdmInput label="Primer (R$)" type="number" value={form.primer} onChange={(value) => update("primer", Number(value))} /><FdmInput label="Tintas (R$)" type="number" value={form.paints} onChange={(value) => update("paints", Number(value))} /><FdmInput label="Aerógrafo / insumos (R$)" type="number" value={form.airbrush} onChange={(value) => update("airbrush", Number(value))} /><FdmInput label="Verniz (R$)" type="number" value={form.varnishCost} onChange={(value) => update("varnishCost", Number(value))} /><FdmInput label="Cola / adesivo (R$)" type="number" value={form.glue} onChange={(value) => update("glue", Number(value))} /><FdmInput label="Outros (R$)" type="number" value={form.otherConsumable} onChange={(value) => update("otherConsumable", Number(value))} /></div><div className="fdm-total-line"><span>Total consumíveis</span><strong>{money(consumables)}</strong></div></FdmCard>
      <FdmCard title="Componentes adicionais" icon={PackageOpen}><div className="form-grid three"><FdmInput label="Suporte / estrutura metálica (R$)" type="number" value={form.support} onChange={(value) => update("support", Number(value))} /><FdmInput label="Iluminação LED interna (R$)" type="number" value={form.led} onChange={(value) => update("led", Number(value))} /><FdmInput label="Base / pedestal (R$)" type="number" value={form.pedestal} onChange={(value) => update("pedestal", Number(value))} /><FdmSelect label="Embalagem" value={form.packageName} options={["", ...settings.packages.map((item) => item.name)]} onChange={(value) => update("packageName", value)} /><FdmInput label="Outros componentes (R$)" type="number" value={form.otherComponent} onChange={(value) => update("otherComponent", Number(value))} /></div><div className="fdm-total-line"><span>Total componentes</span><strong>{money(components)}</strong></div></FdmCard>
      <FdmCard title="Informações de venda" icon={Store}><div className="form-grid two"><div className="channel-field"><FdmSelect label="Canal de venda" value={form.channelName} options={settings.channels.map((channel) => channel.name)} onChange={(value) => update("channelName", value)} /><small>{selectedChannel.commission.toFixed(2)}% de comissão · taxa fixa {money(selectedChannel.fixedFee || 0)}</small></div><FdmInput label="Preço de mercado / referência (R$)" type="number" value={form.marketPrice} onChange={(value) => update("marketPrice", Number(value))} /></div><label className="field fdm-field"><span>Observações</span><textarea value={form.notes} onChange={(event) => update("notes", event.target.value)} placeholder="Detalhes da pintura, negociação ou referência..." /></label></FdmCard>
      <div className="fdm-save-row"><button className="secondary-button" onClick={() => setForm(initial())}><RotateCcw size={14} /> Limpar formulário</button><button className="primary-button" onClick={saveHistory}><Save size={14} /> Salvar no histórico</button></div>
    </div><div className="fdm-result-column"><div className="fdm-sticky">
      <FdmResultCard title="Custo de impressão resina" icon={Droplets}><ResultMetric label={`Resina · ${settings.resinLoss}% perdas`} value={money(resinCost)} /><ResultMetric label="Energia" value={money(energyCost)} /><ResultMetric label="Depreciação" value={money(depreciation)} /><ResultMetric label="Custo de impressão total" value={money(printing)} strong /></FdmResultCard>
      <FdmResultCard title="Mão de obra, consumíveis e indiretos" icon={Paintbrush}><ResultMetric label={`Mão de obra · ${manualHours.toFixed(2)} h × ${money(laborRate)}`} value={money(labor)} /><ResultMetric label="Consumíveis de pintura" value={money(consumables)} /><ResultMetric label="Componentes adicionais" value={money(components)} /><ResultMetric label="Custo indireto rateado" value={money(indirect)} /><ResultMetric label="CUSTO TOTAL DO PRODUTO" value={money(total)} strong /></FdmResultCard>
      <FdmResultCard title="Precificação" icon={ArrowUpRight}><PriceMetric label="Preço mínimo" value={minimum} detail="Sem lucro, já com canal e imposto" /><PriceMetric label="Preço recomendado" value={recommended} detail={`Margem padrão: ${pricingMarginLabel(settings.defaultMargin)}`} /><PriceMetric label="Preço para eventos" value={eventPrice} detail={`+${settings.eventAdditional}% sobre recomendado`} /><label className="field adjusted-field"><span>Preço de venda real (R$)</span><input type="number" step="0.01" value={form.adjustedPrice || ""} placeholder={recommended ? recommended.toFixed(2) : "Digite seu preço"} onChange={(event) => update("adjustedPrice", Number(event.target.value))} /></label></FdmResultCard>
      <FdmResultCard title="Análise da venda" icon={FileBarChart}><div className="analysis-grid"><ResultMetric label="Margem real" value={`${realMargin.toFixed(1)}%`} /><ResultMetric label="Lucro real" value={money(realProfit)} /><ResultMetric label="Taxas do canal" value={money(channelFees)} /><ResultMetric label="Efetivo/h Fábio" value={`${money(effectiveHour)}/h`} strong /><ResultMetric label="Alvo Fábio" value={`${money(laborRate)}/h`} /></div>{(alertLoss || alertLabor || alertMarket || alertPaint) && <div className="fdm-alerts">{alertLoss && <div>⚠️ Venda com prejuízo!</div>}{alertLabor && <div>⚠️ Hora do Fábio subpaga nessa venda</div>}{alertMarket && <div>⚠️ Preço mínimo acima do mercado — rever viabilidade</div>}{alertPaint && <div>⚠️ Peça com pintura sem custo de tintas — verificar</div>}</div>}</FdmResultCard>
      <ResinBreakdown breakdown={breakdown} total={breakdownTotal} gradient={gradient} />
    </div></div></div>
    {showHistory && <div className="fdm-history panel"><div className="history-head"><div><h2>Histórico de produtos Resina + Pintura</h2><p>Produtos salvos e registros importados da planilha histórica.</p></div><div className="search-box"><Search size={14} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por nome..." /></div></div><div className="history-table"><div className="history-row history-head-row"><span>PRODUTO</span><span>IMPRESSÃO</span><span>CUSTO TOTAL</span><span>SUGERIDO</span><span>AJUSTADO</span><span /></div>{history.filter((item) => item.name.toLowerCase().includes(search.toLowerCase())).map((item) => <div className="history-row" key={item.id}><b>{item.name}</b><span>{item.volumeMl} ml · {item.printHours}h{String(item.printMinutes).padStart(2, "0")}</span><span>{money(item.costs.total)}</span><span>{money(item.costs.suggested)}</span><strong>{item.costs.adjusted ? money(item.costs.adjusted) : "A definir"}</strong><div className="history-row-actions"><button onClick={() => loadItem(item)}>Abrir</button><button onClick={() => loadItem(item, true)}>Duplicar</button></div></div>)}</div></div>}
  </PageFrame>;
}

function ResinBreakdown({ breakdown, total, gradient }: { breakdown: { label: string; value: number; color: string }[]; total: number; gradient: string }) { return <div className="panel resin-breakdown"><div className="dashboard-card-head"><div><h2>Composição do custo</h2><p>Distribuição por componente</p></div><PieChart size={16} color="var(--accent)" /></div><div className="breakdown-content"><div className="breakdown-donut" style={{ background: `conic-gradient(${gradient || "#eee 0 100%"})` }}><div><strong>{money(total)}</strong><small>Custo total</small></div></div><div className="breakdown-legend">{breakdown.map((item) => <div key={item.label}><i style={{ background: item.color }} /><span>{item.label}</span><b>{total ? `${(item.value / total * 100).toFixed(0)}%` : "0%"}</b></div>)}</div></div></div>; }

function SettingsPage({ settings, onSave, onNotify }: { settings: GlobalSettings; onSave: (s: GlobalSettings) => void; onNotify: (message: string) => void }) {
  const [draft, setDraft] = useState<GlobalSettings>(() => structuredClone(settings));
  const set = (key: keyof GlobalSettings, value: number | string) => setDraft((s) => ({ ...s, [key]: typeof value === "string" && key === "activeScenario" ? value : Number(value) } as GlobalSettings));
  const scenario = draft.scenarios[draft.activeScenario] || draft.scenarios["Ideal"]!;
  const productiveHours = scenario.hoursPerWeek * scenario.weeksPerMonth;
  const fdmEnergy = draft.fdmPower * draft.fdmKwh;
  const fdmEstimated = draft.fdmPurchase / draft.fdmLife + fdmEnergy;
  const resinEnergy = draft.resinPower * draft.resinKwh;
  const resinDep = draft.resinPurchase / draft.resinLife;
  const indirectTotal = draft.indirect.reduce((sum, item) => sum + item.value, 0);
  const activeHour = productiveHours ? scenario.remuneration / productiveHours : 0;
  const indirectHour = productiveHours ? indirectTotal / productiveHours : 0;
  const consumableTotal = draft.consumables.reduce((sum, item) => sum + item.cost, 0);
  const updateList = (key: "consumables" | "indirect" | "channels" | "packages", index: number, patch: Record<string, string | number | null>) => setDraft((s) => { const list = [...s[key]] as Array<Record<string, unknown>>; list[index] = { ...list[index], ...patch }; return { ...s, [key]: list } as unknown as GlobalSettings; });
  const save = () => { localStorage.setItem("edition-geek-global-settings", JSON.stringify(draft)); onSave(draft); window.dispatchEvent(new Event("edition-geek-settings-changed")); onNotify("Configurações salvas com sucesso"); };
  const restore = () => { if (window.confirm("Restaurar todos os valores padrão?")) { const fresh = structuredClone(defaultSettings); setDraft(fresh); localStorage.setItem("edition-geek-global-settings", JSON.stringify(fresh)); onSave(fresh); onNotify("Padrões restaurados"); } };
  return <PageFrame icon={Settings} title="Configurações globais" subtitle="Parâmetros que alimentam automaticamente toda a precificação" action="Salvar configurações" onAction={save}>
    <div className="settings-actions"><span><Info size={13} /> Alterações aplicadas nas novas e nas fichas de custo abertas.</span><button className="secondary-button" onClick={restore}><RotateCcw size={13} /> Restaurar padrões</button></div>
    <div className="settings-indicators"><Indicator icon={UserCog} label="Valor/hora ativo do Fábio" value={money(activeHour) + "/h"} /><Indicator icon={Receipt} label="Custo indireto por hora" value={money(indirectHour) + "/h"} /><Indicator icon={Zap} label="Energia FDM / Resina" value={`${money(fdmEnergy)}/h · ${money(resinEnergy)}/h`} /></div>
    <div className="settings-grid">
      <SettingsCard title="Parâmetros de impressão FDM" icon={Printer}><div className="form-grid two"><NumberField label="Potência (kW)" value={draft.fdmPower} onChange={(v) => set("fdmPower", v)} /><NumberField label="Preço do kWh (R$)" value={draft.fdmKwh} onChange={(v) => set("fdmKwh", v)} /><NumberField label="Valor de compra (R$)" value={draft.fdmPurchase} onChange={(v) => set("fdmPurchase", v)} /><NumberField label="Vida útil (horas)" value={draft.fdmLife} onChange={(v) => set("fdmLife", v)} /></div><div className="calc-lines"><Metric label="Custo de energia por hora" value={money(fdmEnergy)} /><Metric label="Depreciação por hora" value={money(draft.fdmPurchase / draft.fdmLife)} /><Metric label="Taxa estimada (depreciação + energia)" value={money(fdmEstimated)} /></div><NumberField label="Taxa hora-máquina usada na precificação (R$/h)" value={draft.fdmMachineRate} onChange={(v) => set("fdmMachineRate", v)} /></SettingsCard>
      <SettingsCard title="Parâmetros de impressão resina" icon={PackageOpen}><div className="form-grid two"><NumberField label="Preço da resina (R$/L)" value={draft.resinPrice} onChange={(v) => set("resinPrice", v)} /><NumberField label="Potência (kW)" value={draft.resinPower} onChange={(v) => set("resinPower", v)} /><NumberField label="Preço do kWh (R$)" value={draft.resinKwh} onChange={(v) => set("resinKwh", v)} /><NumberField label="Valor de compra (R$)" value={draft.resinPurchase} onChange={(v) => set("resinPurchase", v)} /><NumberField label="Vida útil (horas)" value={draft.resinLife} onChange={(v) => set("resinLife", v)} /><NumberField label="Perdas/falhas (%)" value={draft.resinLoss} onChange={(v) => set("resinLoss", v)} /></div><div className="calc-lines"><Metric label="Custo de energia por hora" value={money(resinEnergy)} /><Metric label="Depreciação por hora" value={money(resinDep)} /></div></SettingsCard>
      <SettingsCard title="Consumíveis por peça" icon={Boxes}><div className="settings-table"><div className="settings-table-head"><span>CONSUMÍVEL</span><span>CUSTO/PEÇA</span><span>REFERÊNCIA</span></div>{draft.consumables.map((item, i) => <div className="settings-table-row" key={item.name}><span>{item.name}</span><input type="number" step="0.01" value={item.cost} onChange={(e) => updateList("consumables", i, { cost: Number(e.target.value) })} /><small>{item.reference}</small></div>)}<div className="settings-total"><b>TOTAL CONSUMÍVEIS</b><strong>{money(consumableTotal)}</strong></div></div></SettingsCard>
      <SettingsCard title="Valor/hora do Fábio" icon={UserCog}><div className="scenario-tabs">{Object.keys(draft.scenarios).map((name) => <button className={draft.activeScenario === name ? "selected" : ""} onClick={() => set("activeScenario", name)} key={name}>Cenário {name}</button>)}</div>{Object.entries(draft.scenarios).map(([name, item]) => <div className={`scenario-row ${draft.activeScenario === name ? "active" : ""}`} key={name}><b>{name}</b><NumberField label="Remuneração mensal (R$)" value={item.remuneration} onChange={(v) => setDraft((s) => ({ ...s, scenarios: { ...s.scenarios, [name]: { ...item, remuneration: v } } }))} /><NumberField label="Horas/semana" value={item.hoursPerWeek} onChange={(v) => setDraft((s) => ({ ...s, scenarios: { ...s.scenarios, [name]: { ...item, hoursPerWeek: v } } }))} /><NumberField label="Semanas/mês" value={item.weeksPerMonth} onChange={(v) => setDraft((s) => ({ ...s, scenarios: { ...s.scenarios, [name]: { ...item, weeksPerMonth: v } } }))} /><div className="scenario-result"><small>{(item.hoursPerWeek * item.weeksPerMonth).toFixed(2)} h/mês</small><strong>{money(item.hoursPerWeek * item.weeksPerMonth ? item.remuneration / (item.hoursPerWeek * item.weeksPerMonth) : 0)}/h</strong></div></div>)}<div className="active-highlight"><span>Valor/hora ativo</span><strong>{money(activeHour)}/h</strong></div><small className="helper-text">Impressão e secagem sem acompanhamento não contam como hora produtiva.</small></SettingsCard>
      <SettingsCard title="Custos indiretos mensais" icon={Receipt}><div className="settings-table">{draft.indirect.map((item, i) => <div className="settings-table-row" key={item.name}><span>{item.name}</span><input type="number" step="0.01" value={item.value} onChange={(e) => updateList("indirect", i, { value: Number(e.target.value) })} /></div>)}<div className="settings-total"><b>TOTAL MENSAL</b><strong>{money(indirectTotal)}</strong></div></div><div className="rate-highlight"><span>Rateio · {productiveHours.toFixed(2)} horas produtivas/mês</span><strong>{money(indirectHour)}/h</strong></div></SettingsCard>
      <SettingsCard title="Margens e política de preços" icon={Percent}><div className="form-grid three"><NumberField label="Margem de lucro padrão (%)" value={draft.defaultMargin} onChange={(v) => set("defaultMargin", v)} /><NumberField label="Adicional para eventos (%)" value={draft.eventAdditional} onChange={(v) => set("eventAdditional", v)} /><NumberField label="Imposto sobre venda (%)" value={draft.salesTax} onChange={(v) => set("salesTax", v)} /></div><div className="formula-box"><b>Fórmula usada na precificação</b><code>Preço = Custo Total ÷ (1 − margem% − taxas_canal% − imposto%)</code><small>100% configurado significa dobrar o custo e é convertido para 50% efetivos na fórmula, evitando divisão por zero.</small></div></SettingsCard>
      <SettingsCard title="Canais de venda" icon={Store} wide><EditableTable headers={["Canal", "Comissão (%)", "Taxa fixa/item", "Observação"]}>{draft.channels.map((item, i) => <div className="settings-table-row" key={i}><input value={item.name} onChange={(e) => updateList("channels", i, { name: e.target.value })} /><input type="number" step="0.01" value={item.commission} onChange={(e) => updateList("channels", i, { commission: Number(e.target.value) })} /><input type="number" step="0.01" value={item.fixedFee} onChange={(e) => updateList("channels", i, { fixedFee: Number(e.target.value) })} /><input value={item.note} onChange={(e) => updateList("channels", i, { note: e.target.value })} /><button className="icon-danger" onClick={() => setDraft((s) => ({ ...s, channels: s.channels.filter((_, n) => n !== i) }))}><Trash2 size={14} /></button></div>)}</EditableTable><button className="secondary-button" onClick={() => setDraft((s) => ({ ...s, channels: [...s.channels, { name: "Novo canal", commission: 0, fixedFee: 0, note: "" }] }))}><Plus size={13} /> Adicionar canal</button></SettingsCard>
      <SettingsCard title="Embalagens" icon={Package} wide><EditableTable headers={["Embalagem", "Custo (R$)"]}>{draft.packages.map((item, i) => <div className="settings-table-row" key={i}><input value={item.name} onChange={(e) => updateList("packages", i, { name: e.target.value })} /><input type="number" step="0.01" value={item.cost ?? ""} placeholder="—" onChange={(e) => updateList("packages", i, { cost: e.target.value === "" ? null : Number(e.target.value) })} /><button className="icon-danger" onClick={() => setDraft((s) => ({ ...s, packages: s.packages.filter((_, n) => n !== i) }))}><Trash2 size={14} /></button></div>)}</EditableTable><button className="secondary-button" onClick={() => setDraft((s) => ({ ...s, packages: [...s.packages, { name: "Nova embalagem", cost: 0 }] }))}><Plus size={13} /> Adicionar embalagem</button></SettingsCard>
    </div>
  </PageFrame>;
}

function timeToHours(value: string) { const [hours, minutes] = value.split(":").map(Number); return (hours || 0) + (minutes || 0) / 60; }
function formatHours(value: number) { const hours = Math.floor(value); return `${String(hours).padStart(2, "0")}:${String(Math.round((value - hours) * 60)).padStart(2, "0")}`; }
function parseCsvLine(line: string) { return line.split(/[,;\t]/).map((cell) => cell.trim().replace(/^['"]|['"]$/g, "")); }

function FdmCalculator({ settings, onNotify }: { settings: GlobalSettings; onNotify: (message: string) => void }) {
  const [form, setForm] = useState<FdmForm>(() => emptyFdmForm());
  const [history, setHistory] = useState<FdmHistoryItem[]>(() => { try { return JSON.parse(localStorage.getItem("edition-geek-fdm-history") || "null") || initialFdmHistory; } catch { return initialFdmHistory; } });
  const [search, setSearch] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const selectedChannel = settings.channels.find((channel) => channel.name === form.channelName) || settings.channels[0] || { commission: 0, fixedFee: 0, name: "Pix", note: "—" };
  const selectedPackage = settings.packages.find((item) => item.name === form.packageName);
  const printHours = form.printHours + form.printMinutes / 60;
  const serviceHours = timeToHours(form.design) + timeToHours(form.slicing) + timeToHours(form.finishing);
  const material = form.materialGrams / 1000 * form.filamentKg;
  const machine = printHours * settings.fdmMachineRate;
  const energy = printHours * settings.fdmPower * settings.fdmKwh;
  const fabrication = material + machine + energy;
  const service = serviceHours * activeLaborRate(settings);
  const indirect = serviceHours * activeIndirectRate(settings);
  const components = form.led + form.powerSupply + form.otherCost + (selectedPackage?.cost || 0);
  const total = fabrication + service + components + indirect;
  const commission = (selectedChannel.commission || 0) / 100;
  const tax = settings.salesTax / 100;
  const minDenominator = 1 - commission - tax;
  const recommendedDenominator = 1 - pricingMarginFraction(settings.defaultMargin) - commission - tax;
  const minimum = minDenominator > 0 ? total / minDenominator : 0;
  const recommended = recommendedDenominator > 0 ? total / recommendedDenominator : 0;
  const eventPrice = recommended * (1 + settings.eventAdditional / 100);
  const adjusted = form.adjustedPrice || recommended;
  const channelFee = adjusted * commission + (selectedChannel.fixedFee || 0);
  const realMargin = adjusted > 0 ? (adjusted - total) / adjusted * 100 : 0;
  const realProfit = adjusted - total - channelFee;
  const effectiveHour = serviceHours > 0 ? realProfit / serviceHours : 0;
  const targetHour = activeLaborRate(settings);
  const update = (key: keyof FdmForm, value: string | number) => setForm((current) => ({ ...current, [key]: value }));
  const costs = { fabrication, service, components, indirect, total, suggested: recommended, adjusted };
  const saveHistory = () => { const item: FdmHistoryItem = { ...form, id: `${Date.now()}`, savedAt: new Date().toLocaleString("pt-BR"), costs }; const next = [item, ...history]; setHistory(next); localStorage.setItem("edition-geek-fdm-history", JSON.stringify(next)); onNotify("Ficha salva no histórico"); };
  const loadItem = (item: FdmHistoryItem, duplicate = false) => { const { id: _id, costs: _costs, savedAt: _savedAt, ...formValues } = item; setForm({ ...formValues, name: duplicate ? `${item.name} · cópia` : item.name }); setShowHistory(false); };
  const attachStl = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; if (!file.name.toLowerCase().endsWith(".stl")) { onNotify("Selecione um arquivo STL válido"); event.target.value = ""; return; } const reader = new FileReader(); reader.onload = () => { setForm((current) => ({ ...current, stlFileName: file.name, stlDataUrl: String(reader.result || "") })); onNotify(`${file.name} anexado à ficha`); }; reader.readAsDataURL(file); event.target.value = ""; };
  const importCsv = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const lines = String(reader.result || "").split(/\r?\n/).filter(Boolean); if (lines.length < 2) return; const headers = parseCsvLine(lines[0] || "").map((header) => header.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")); const imported = lines.slice(1).map((line, index) => { const values = parseCsvLine(line); const value = (names: string[]) => { const position = headers.findIndex((header) => names.some((name) => header.includes(name))); return position >= 0 ? values[position] || "" : ""; }; const grams = Number(value(["gramas", "material"]).replace(",", ".")) || 0; const price = Number(value(["venda ajustada", "ajustado"]).replace(",", ".")) || 0; return { ...emptyFdmForm(), id: `csv-${Date.now()}-${index}`, name: value(["nome", "produto"]) || `Produto importado ${index + 1}`, materialGrams: grams, printHours: Number(value(["horas impressao", "horas de impressao", "horas"]).replace(",", ".")) || 0, adjustedPrice: price, savedAt: "Importado via CSV", costs: { fabrication: Number(value(["custo fabricacao", "custo de fabricacao"]).replace(",", ".")) || 0, service: Number(value(["custo servico", "custo de servico"]).replace(",", ".")) || 0, components: Number(value(["custo componentes", "custo de componentes"]).replace(",", ".")) || 0, indirect: 0, total: Number(value(["custo total"]).replace(",", ".")) || 0, suggested: Number(value(["valor venda sugerido", "sugerido"]).replace(",", ".")) || 0, adjusted: price } }; }); const next = [...imported, ...history]; setHistory(next); localStorage.setItem("edition-geek-fdm-history", JSON.stringify(next)); onNotify(`${imported.length} produto(s) importado(s)`); }; reader.readAsText(file, "UTF-8"); event.target.value = ""; };
  const alertLoss = adjusted > 0 && adjusted < minimum;
  const alertLabor = serviceHours > 0 && effectiveHour < targetHour;
  const alertMarket = form.marketPrice > 0 && minimum > form.marketPrice;
  return <PageFrame icon={Calculator} title="Calculadora Filamento" subtitle="Custo e preço de venda para peças em PLA nas Bambu Lab A1" action="Novo produto" onAction={() => setForm(emptyFdmForm())}>
    <div className="fdm-toolbar"><div className="fdm-context"><Zap size={15} /><span>Parâmetros globais ativos · máquina {money(settings.fdmMachineRate)}/h · Fábio {money(targetHour)}/h</span></div><div className="fdm-actions"><button className="secondary-button" onClick={() => setShowHistory((value) => !value)}><ClipboardList size={13} /> Histórico ({history.length})</button><label className="secondary-button file-button"><Tags size={13} /> Importar CSV<input type="file" accept=".csv,.tsv" onChange={importCsv} /></label><button className="secondary-button" onClick={() => window.print()}><Receipt size={13} /> Exportar PDF</button></div></div>
    <div className="fdm-layout"><div className="fdm-form-column">
      <FdmCard title="Identificação do produto" icon={Gem}><div className="form-grid two"><FdmInput label="Nome do produto / projeto" value={form.name} onChange={(value) => update("name", value)} placeholder="Ex: Dragão articulado" /><FdmSelect label="Categoria" value={form.category} options={["Decoração", "Colecionável", "Chaveiro", "Pokébola", "Espada Anime", "Estátua", "Caixa/Organizador", "Acessório", "Evento", "Outro"]} onChange={(value) => update("category", value)} /><FdmSelect label="Status" value={form.status} options={["Em produção", "Pronto para venda", "Vendido", "Cancelado"]} onChange={(value) => update("status", value)} /><FdmSelect label="Complexidade" value={form.complexity} options={["Simples", "Intermediária", "Complexa-Premium"]} onChange={(value) => update("complexity", value)} /></div><div className="form-grid two fdm-source-row"><label className="field fdm-field"><span>Link do projeto / modelo</span><div className="source-input"><input className="yellow-input" type="url" value={form.projectUrl} onChange={(event) => update("projectUrl", event.target.value)} placeholder="https://makerworld.com/pt/models/..." />{form.projectUrl && <a href={form.projectUrl} target="_blank" rel="noreferrer" aria-label="Abrir link do projeto">Abrir</a>}</div><small className="field-hint">MakerWorld ou qualquer outra fonte do modelo.</small></label><div className="field fdm-field"><span>Arquivo STL</span><label className="stl-dropzone"><input type="file" accept=".stl,model/stl" onChange={attachStl} /><PackageOpen size={17} /><span>{form.stlFileName || "Clique para anexar o STL"}</span><small>{form.stlFileName ? "Arquivo salvo junto desta ficha" : "Apenas arquivos .stl"}</small></label>{form.stlDataUrl && <div className="stl-actions"><a href={form.stlDataUrl} download={form.stlFileName}>Baixar {form.stlFileName}</a><button type="button" onClick={() => setForm((current) => ({ ...current, stlFileName: "", stlDataUrl: "" }))}>Remover</button></div>}</div></div></FdmCard>
      <FdmCard title="Parâmetros de impressão" icon={Printer}><div className="form-grid three"><FdmInput label="Custo do filamento (R$/kg)" type="number" value={form.filamentKg} onChange={(value) => update("filamentKg", Number(value))} /><FdmInput label="Material gasto (g)" type="number" value={form.materialGrams} onChange={(value) => update("materialGrams", Number(value))} /><div className="fdm-time-group"><span>Tempo de impressão</span><div><FdmInput label="Horas" type="number" value={form.printHours} onChange={(value) => update("printHours", Number(value))} /><FdmInput label="Minutos" type="number" value={form.printMinutes} onChange={(value) => update("printMinutes", Number(value))} /></div></div></div></FdmCard>
      <FdmCard title="Tempo de serviço do Fábio" icon={UserCog}><p className="fdm-helper">Considere apenas o trabalho manual. Impressão automática e secagem ficam fora.</p><div className="form-grid three"><FdmInput label="Projeto / design (hh:mm)" value={form.design} onChange={(value) => update("design", value)} placeholder="00:00" /><FdmInput label="Fatiamento / slicing (hh:mm)" value={form.slicing} onChange={(value) => update("slicing", value)} placeholder="00:00" /><FdmInput label="Montagem / acabamento (hh:mm)" value={form.finishing} onChange={(value) => update("finishing", value)} placeholder="00:00" /></div><div className="fdm-total-line"><span>Total de horas de serviço</span><strong>{formatHours(serviceHours)} · {serviceHours.toFixed(2)} h</strong></div></FdmCard>
      <FdmCard title="Componentes adicionais" icon={Boxes}><div className="form-grid three"><FdmInput label="Fita LED (R$)" type="number" value={form.led} onChange={(value) => update("led", Number(value))} /><FdmInput label="Fonte de alimentação (R$)" type="number" value={form.powerSupply} onChange={(value) => update("powerSupply", Number(value))} /><FdmInput label="Valor (R$)" type="number" value={form.otherCost} onChange={(value) => update("otherCost", Number(value))} /><FdmInput label="Descrição do item" value={form.otherLabel} onChange={(value) => update("otherLabel", value)} placeholder="Pintura, chaveiro, outros..." /><FdmSelect label="Embalagem" value={form.packageName} options={["", ...settings.packages.map((item) => item.name)]} onChange={(value) => update("packageName", value)} /></div><div className="fdm-total-line"><span>Total de componentes</span><strong>{money(components)}</strong></div></FdmCard>
      <FdmCard title="Informações de venda" icon={Store}><div className="form-grid two"><div className="channel-field"><FdmSelect label="Canal de venda" value={form.channelName} options={settings.channels.map((channel) => channel.name)} onChange={(value) => update("channelName", value)} /><small>{selectedChannel.commission.toFixed(2)}% de comissão · taxa fixa {money(selectedChannel.fixedFee || 0)}</small></div><FdmInput label="Preço de mercado / concorrente (R$)" type="number" value={form.marketPrice} onChange={(value) => update("marketPrice", Number(value))} /></div><label className="field fdm-field"><span>Observações</span><textarea value={form.notes} onChange={(event) => update("notes", event.target.value)} placeholder="Observações sobre a peça, concorrência ou negociação..." /></label></FdmCard>
      <div className="fdm-save-row"><button className="secondary-button" onClick={() => setForm(emptyFdmForm())}><RotateCcw size={14} /> Limpar formulário</button><button className="primary-button" onClick={saveHistory}><Save size={14} /> Salvar no histórico</button></div>
    </div><div className="fdm-result-column"><div className="fdm-sticky">
      <FdmResultCard title="Custo de fabricação" icon={Printer}><ResultMetric label="Material" value={money(material)} /><ResultMetric label="Hora-máquina" value={money(machine)} /><ResultMetric label="Energia" value={money(energy)} /><ResultMetric label="Custo de fabricação total" value={money(fabrication)} strong /></FdmResultCard>
      <FdmResultCard title="Custo de serviço e indiretos" icon={UserCog}><ResultMetric label={`Serviço · ${serviceHours.toFixed(2)} h × ${money(targetHour)}`} value={money(service)} /><ResultMetric label="Custo indireto rateado" value={money(indirect)} /><ResultMetric label="Componentes" value={money(components)} /><ResultMetric label="CUSTO TOTAL DO PRODUTO" value={money(total)} strong /></FdmResultCard>
      <FdmResultCard title="Precificação" icon={ArrowUpRight}><PriceMetric label="Preço mínimo" value={minimum} detail="Sem lucro, já com canal e imposto" /><PriceMetric label="Preço recomendado" value={recommended} detail={`Margem padrão: ${pricingMarginLabel(settings.defaultMargin)}`} /><PriceMetric label="Preço para eventos" value={eventPrice} detail={`+${settings.eventAdditional}% sobre recomendado`} /><label className="field adjusted-field"><span>Valor de venda ajustado (R$)</span><input type="number" step="0.01" value={form.adjustedPrice || ""} placeholder={recommended ? recommended.toFixed(2) : "Digite seu preço"} onChange={(event) => update("adjustedPrice", Number(event.target.value))} /></label></FdmResultCard>
      <FdmResultCard title="Análise da venda" icon={FileBarChart}><div className="analysis-grid"><ResultMetric label="Margem real" value={`${realMargin.toFixed(1)}%`} /><ResultMetric label="Lucro real" value={money(realProfit)} /><ResultMetric label="Taxas do canal" value={money(channelFee)} /><ResultMetric label="Efetivo/h Fábio" value={`${money(effectiveHour)}/h`} strong /><ResultMetric label="Alvo Fábio" value={`${money(targetHour)}/h`} /></div>{(alertLoss || alertLabor || alertMarket) && <div className="fdm-alerts">{alertLoss && <div>⚠️ Venda com prejuízo!</div>}{alertLabor && <div>⚠️ Hora do Fábio subpaga nessa venda</div>}{alertMarket && <div>⚠️ Preço mínimo acima do mercado — rever viabilidade</div>}</div>}</FdmResultCard>
    </div></div></div>
    {showHistory && <div className="fdm-history panel"><div className="history-head"><div><h2>Histórico de produtos FDM</h2><p>Produtos salvos e registros importados da planilha histórica.</p></div><div className="search-box"><Search size={14} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por nome..." /></div></div><div className="history-table"><div className="history-row history-head-row"><span>PRODUTO</span><span>MATERIAL</span><span>CUSTO TOTAL</span><span>SUGERIDO</span><span>AJUSTADO</span><span /></div>{history.filter((item) => item.name.toLowerCase().includes(search.toLowerCase())).map((item) => <div className="history-row" key={item.id}><b className="history-product"><span>{item.name}</span><small>{item.projectUrl ? <a href={item.projectUrl} target="_blank" rel="noreferrer">Projeto ↗</a> : "Sem link"}{item.stlFileName && <em title={item.stlFileName}>STL</em>}</small></b><span>{item.materialGrams} g · {item.printHours}h{String(item.printMinutes).padStart(2, "0")}</span><span>{money(item.costs.total)}</span><span>{money(item.costs.suggested)}</span><strong>{money(item.costs.adjusted)}</strong><div className="history-row-actions"><button onClick={() => loadItem(item)}>Abrir</button><button onClick={() => loadItem(item, true)}>Duplicar</button></div></div>)}</div></div>}
  </PageFrame>;
}

function activeLaborRate(settings: GlobalSettings) { const scenario = settings.scenarios[settings.activeScenario] || settings.scenarios["Ideal"]!; const hours = scenario.hoursPerWeek * scenario.weeksPerMonth; return hours ? scenario.remuneration / hours : 0; }
function activeIndirectRate(settings: GlobalSettings) { const scenario = settings.scenarios[settings.activeScenario] || settings.scenarios["Ideal"]!; const hours = scenario.hoursPerWeek * scenario.weeksPerMonth; const total = settings.indirect.reduce((sum, item) => sum + item.value, 0); return hours ? total / hours : 0; }
function readProductHistory(settings: GlobalSettings): HistoryProduct[] { try { const fdm: FdmHistoryItem[] = JSON.parse(localStorage.getItem("edition-geek-fdm-history") || "[]"); const resin: ResinHistoryItem[] = JSON.parse(localStorage.getItem("edition-geek-resin-history") || "[]"); const laborRate = activeLaborRate(settings); const mapFdm = fdm.map((item): HistoryProduct => { const price = item.costs.adjusted || 0; const status: HistoryProduct["status"] = item.status === "Vendido" ? "Vendido" : item.status === "Cancelado" ? "Cancelado" : "À venda"; const profit = price > 0 ? price - item.costs.total - price * 0 : 0; return { id: item.id, name: item.name || "Produto FDM sem nome", type: "FDM", category: item.category, complexity: item.complexity, workHours: timeToHours(item.design) + timeToHours(item.slicing) + timeToHours(item.finishing), totalCost: item.costs.total, chargedPrice: price, announcedPrice: item.costs.suggested || price, channel: item.channelName, margin: price > 0 ? profit / price * 100 : 0, profit, effectiveHour: item.costs.total && (timeToHours(item.design) + timeToHours(item.slicing) + timeToHours(item.finishing)) > 0 ? profit / (timeToHours(item.design) + timeToHours(item.slicing) + timeToHours(item.finishing)) : laborRate, targetHour: laborRate, status, completedAt: item.savedAt, notes: item.notes, source: "FDM", detail: item }; }); const mapResin = resin.map((item): HistoryProduct => { const price = item.costs.adjusted || 0; const manual = [item.cleaning, item.sanding, item.primerBase, item.painting, item.varnish, item.assembly].reduce((sum, value) => sum + timeToHours(value), 0); const channel = settings.channels.find((entry) => entry.name === item.channelName); const profit = price > 0 ? price - item.costs.total - price * ((channel?.commission || 0) / 100) - (channel?.fixedFee || 0) : 0; const status: HistoryProduct["status"] = item.status === "Vendido" ? "Vendido" : item.status === "Cancelado" ? "Cancelado" : "À venda"; return { id: item.id, name: item.name || "Produto de resina sem nome", type: "Resina + Pintura", category: item.category, complexity: item.complexity, workHours: manual, totalCost: item.costs.total, chargedPrice: price, announcedPrice: item.costs.suggested || price, channel: item.channelName, margin: price > 0 ? profit / price * 100 : 0, profit, effectiveHour: manual > 0 ? profit / manual : laborRate, targetHour: laborRate, status, completedAt: item.savedAt, notes: item.notes, source: "RESIN", detail: item }; }); return [...baseHistoryProducts, ...mapFdm, ...mapResin]; } catch { return baseHistoryProducts; } }
function FdmCard({ title, icon: Icon, children }: { title: string; icon: LucideIcon; children: ReactNode }) { return <div className="panel fdm-card"><SectionTitle title={title} icon={Icon} />{children}</div>; }
function FdmInput({ label, value, onChange, type = "text", placeholder }: { label: string; value: string | number; onChange: (value: string) => void; type?: string; placeholder?: string }) { return <label className="field fdm-field"><span>{label}</span><input className="yellow-input" type={type} value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} /></label>; }
function FdmSelect({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { const finalOptions = label === "Status" && options.includes("Pronto para venda") && !options.includes("Orçamento") ? ["Em produção", "Orçamento", ...options.filter((option) => option !== "Em produção")] : options; return <label className="field fdm-field"><span>{label}</span><select className="yellow-input" value={value} onChange={(event) => onChange(event.target.value)}>{finalOptions.map((option) => <option key={option} value={option}>{option || "Nenhuma"}</option>)}</select></label>; }
function FdmResultCard({ title, icon: Icon, children }: { title: string; icon: LucideIcon; children: ReactNode }) { return <div className="panel fdm-result-card"><SectionTitle title={title} icon={Icon} />{children}</div>; }
function ResultMetric({ label, value, strong }: { label: string; value: string; strong?: boolean }) { return <div className={`result-metric ${strong ? "strong" : ""}`}><span>{label}</span><b>{value}</b></div>; }
function PriceMetric({ label, value, detail }: { label: string; value: number; detail: string }) { return <div className="price-metric"><div><span>{label}</span><small>{detail}</small></div><strong>{value > 0 ? money(value) : "—"}</strong></div>; }

function Indicator({ icon: Icon, label, value }: { icon: LucideIcon; label: string; value: string }) { return <div className="settings-indicator"><span><Icon size={15} /></span><div><small>{label}</small><strong>{value}</strong></div></div>; }
function SettingsCard({ title, icon: Icon, children, wide }: { title: string; icon: LucideIcon; children: ReactNode; wide?: boolean }) { return <div className={`panel settings-card ${wide ? "wide" : ""}`}><SectionTitle title={title} icon={Icon} />{children}</div>; }
function NumberField({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) { return <label className="field"><span>{label}</span><input type="number" step="0.01" value={value} onChange={(e) => onChange(Number(e.target.value))} /></label>; }
function EditableTable({ headers, children }: { headers: string[]; children: ReactNode }) { return <div className="settings-table editable"><div className="settings-table-head">{headers.map((h) => <span key={h}>{h}</span>)}</div>{children}</div>; }

function PricingPage({ onNotify, settings }: { onNotify: (message: string) => void; settings: GlobalSettings }) {
  const active = settings.scenarios[settings.activeScenario] || settings.scenarios["Ideal"]!;
  const activeHour = active.hoursPerWeek * active.weeksPerMonth ? active.remuneration / (active.hoursPerWeek * active.weeksPerMonth) : 0;
  const indirectHour = active.hoursPerWeek * active.weeksPerMonth ? settings.indirect.reduce((sum, item) => sum + item.value, 0) / (active.hoursPerWeek * active.weeksPerMonth) : 0;
  return <PageFrame icon={Calculator} title="Produto 1" subtitle="Monte sua peça e descubra o preço ideal" action="Salvar" onAction={() => onNotify("Produto salvo") }><div className="pricing-live-strip"><span><UserCog size={14} /> Mão de obra: <b>{money(activeHour)}/h</b></span><span><Wrench size={14} /> Indiretos: <b>{money(indirectHour)}/h</b></span><span><Zap size={14} /> Máquina FDM: <b>{money(settings.fdmMachineRate)}/h</b></span></div><div className="pricing-grid"><div className="panel form-panel"><SectionTitle title="Produto 1" icon={Gem} /><div className="form-grid two"><Field label="Nome do Produto" placeholder="Ex: Porta-canetas personalizado" /><Field label="Quantidade" placeholder="1" /></div><Field label="Descrição / Especificações" placeholder="Detalhes, especificações, observações do produto..." area /><SectionTitle title="Modelagem e Impressão" icon={Printer} small /><div className="form-grid three"><Field label="Modelagem e Impressão" placeholder="Nenhum" select /><Field label="Geral (min)" placeholder="0" /><Field label="Por peça (min)" placeholder="0" /></div><div className="form-grid three"><Field label="Aquisição de Modelo (R$)" placeholder="0,00" /><Field label="Retrabalho (%)" placeholder="0" /><Field label="Urgência (%)" placeholder="0" /></div><div className="highlight-box"><SectionTitle title="Dados Unitários" icon={Calculator} small /><div className="form-grid four"><Field label="Tempo de Impressão" placeholder="Nenhum" select /><Field label="Dias" placeholder="0" /><Field label="Horas" placeholder="0" /><Field label="Minutos" placeholder="0" /></div><button className="secondary-button"><Plus size={14} /> Adicionar impressora</button></div></div><div className="pricing-side"><div className="panel form-panel"><SectionTitle title="Custos Gerais da Venda" icon={Boxes} /><div className="form-grid two"><Field label="Canal de venda" placeholder="Pix" select /><Field label="Tempo (min)" placeholder="0" /></div><Field label="Embalagem" placeholder={settings.packages[0]?.name || "Nenhuma"} select /><button className="secondary-button"><Plus size={14} /> Adicionar embalagem</button></div><div className="panel result-panel"><SectionTitle title="Resultado da Precificação" icon={ArrowUpRight} /><p className="subsection-label">Detalhamento de Custos</p><Metric label="Custo de Produção" value="R$ 0,00" /><Metric label="Custos Totais" value="R$ 0,00" danger /><div className="notice"><Wrench size={14} /> Configurações globais conectadas. Os valores são atualizados ao salvar.</div><p className="subsection-label">Margem de Lucro Desejada</p><div className="profit-slider"><i /><b>{settings.defaultMargin}%</b></div><div className="slider-labels"><span>0%</span><span>50%</span><span>100%</span><span>150%</span></div></div></div></div></PageFrame>;
}

function OrdersPage({ onAdd }: { onAdd: () => void }) { return <PageFrame icon={Package} title="Controle de Pedidos" subtitle="Acompanhe e gerencie os pedidos da sua loja" action="Pedido Rápido" onAction={onAdd}><div className="filter-row"><div className="filter-tabs"><button className="selected">Todos</button><button>Em aberto</button><button>Em produção</button><button>Concluídos</button></div><div className="search-box"><Search size={15} /><input placeholder="Buscar por nome ou número..." /></div></div><div className="panel table-panel"><div className="table-head"><span>PEDIDO</span><span>CLIENTE</span><span>STATUS</span><span>ENTREGA</span><span>VALOR</span><span /></div>{transactions.map((item, index) => <div className="table-row" key={item.id}><div className="transaction-name"><span className="transaction-icon out"><Package size={15} /></span><b>#{2048 - index}</b></div><span className="category">{index === 0 ? "Ana Souza" : index === 1 ? "Carlos Lima" : "Mariana Geek"}</span><span className={`status ${index === 1 ? "in" : "pending"}`}>{index === 1 ? "Concluído" : "Em aberto"}</span><span className="date">15 ago, 2026</span><strong>R$ {index === 0 ? "320,00" : index === 1 ? "890,00" : "145,00"}</strong><button className="row-more"><MoreHorizontal size={17} /></button></div>)}</div></PageFrame>; }

function FinancialPage() { return <PageFrame icon={Wallet} title="Controle Financeiro" subtitle="Gerencie receitas, despesas e analise a saúde financeira do seu negócio" action="Nova Transação"><div className="filter-tabs wide"><button>Transações</button><button>Recebimentos Pendentes</button><button>Gráficos</button><button className="selected">Fluxo de Caixa</button></div><div className="period-panel"><button>Total</button><button>Anual</button><button className="selected">Mensal</button><button><CalendarDays size={14} /> Personalizado</button><ChevronLeft size={16} /><b>Agosto de 2026</b><ChevronRight size={16} /></div><div className="panel empty-chart"><h3>Fluxo de Caixa com Projeção</h3><p>Histórico e projeção dos próximos meses</p><span>Nenhum dado disponível</span></div></PageFrame>; }

function ResourcesPage() { return <PageFrame icon={Boxes} title="Recursos" subtitle="Gerencie os materiais e recursos usados na produção" action="Novo Acabamento"><div className="filter-tabs resource-tabs"><button>Matéria-prima</button><button className="selected">Acabamentos</button><button>Embalagens</button><button>Maquinários</button><button>Profissionais</button></div><div className="panel empty-state"><Boxes size={34} /><h3>Nenhum acabamento cadastrado</h3><p>Adicione seus materiais de acabamento</p></div></PageFrame>; }

function StorePage() { return <PageFrame icon={Store} title="Minha Loja Online" subtitle="Sua loja pra vender direto pro cliente — montada com os produtos que você já tem no 3DPM." action=""><div className="panel store-empty"><Store size={31} /><h2>Sua loja nasce pronta pra vender</h2><p>Uma loja online ou um link integrado aos produtos que você já cadastrou aparecem sozinhos na loja.</p></div><div className="setup-steps"><SetupStep number="1" title="Criar sua loja" detail="A gente monta sua loja com seus produtos em 1 clique." action="Criar minha loja grátis"/><SetupStep number="2" title="Receber os pagamentos" detail="Conecte o Mercado Pago pra o dinheiro das vendas cair na sua conta." action="Conectar Mercado Pago" disabled/></div><div className="panel fees-note"><b>Você só paga quando vende:</b><span>Pix — 3,9% por venda</span><span>Cartão — 6,9% por venda</span></div></PageFrame>; }

function UsersPage({ onAdd }: { onAdd: () => void }) { return <PageFrame icon={UsersRound} title="Usuários" subtitle="Gerencie quem pode acessar seu workspace" action="Novo Usuário" onAction={onAdd}><div className="filter-tabs settings-tabs"><button>Perfil</button><button className="selected">Usuários</button><button>Perfis</button><button>Categorias</button><button>Entregas</button><button>Calculadora</button></div><div className="toolbar-row"><div className="search-box"><Search size={15} /><input placeholder="Buscar por nome ou email..." /></div><select><option>Todos Perfis</option></select><span className="usage-pill">0/3 utilizados</span></div><div className="panel empty-state"><UsersRound size={34} /><h3>Nenhum usuário encontrado</h3><p>Adicione usuários para compartilhar o acesso ao sistema</p></div></PageFrame>; }

function EmptyPage({ title, subtitle, icon: Icon, action, empty, onAdd }: { title: string; subtitle: string; icon: LucideIcon; action: string; empty: string; onAdd: () => void }) { return <PageFrame icon={Icon} title={title} subtitle={subtitle} action={action} onAction={onAdd}><div className="toolbar-row"><div className="search-box"><Search size={15} /><input placeholder={`Buscar em ${title.toLowerCase()}...`} /></div><button className="secondary-button"><CalendarDays size={14} /> Todos</button></div><div className="panel empty-state"><Icon size={34} /><h3>{empty}</h3><p>Adicione um novo registro para começar</p></div></PageFrame>; }

function PageFrame({ icon: Icon, title, subtitle, action, onAction, children }: { icon: LucideIcon; title: string; subtitle: string; action?: string; onAction?: () => void; children: ReactNode }) { return <section className="content-page"><div className="page-heading section-heading"><div><h1><Icon size={21} /> {title}</h1><p className="subtitle">{subtitle}</p></div>{action && <button className="primary-button" onClick={onAction}><Plus size={16} /> {action}</button>}</div>{children}</section>; }
function SectionTitle({ title, icon: Icon, small }: { title: string; icon: LucideIcon; small?: boolean }) { return <div className={`section-title ${small ? "small" : ""}`}><Icon size={small ? 14 : 16} /><b>{title}</b></div>; }
function Field({ label, placeholder, select, area }: { label: string; placeholder: string; select?: boolean; area?: boolean }) { return <label className="field"><span>{label}</span>{area ? <textarea placeholder={placeholder} /> : select ? <select><option>{placeholder}</option></select> : <input placeholder={placeholder} />}</label>; }
function Metric({ label, value, danger }: { label: string; value: string; danger?: boolean }) { return <div className="metric"><span>{label}</span><b className={danger ? "danger" : ""}>{value}</b></div>; }
function SetupStep({ number, title, detail, action, disabled }: { number: string; title: string; detail: string; action: string; disabled?: boolean }) { return <div className="setup-step"><span>{number}</span><div><b>{title}</b><p>{detail}</p></div><button disabled={disabled}>{action}</button></div>; }
function parseBr(value: string) { return Number(String(value).replace(/\./g, "").replace(",", ".")) || 0; }
function wizardDefaults(settings: GlobalSettings): WizardForm { return { name: "", type: "FDM", category: "Decoração", complexity: "Simples", status: "Em produção", filamentKg: "120,00", grams: "", resinLiter: "150,00", volumeMl: "", printer: "Elegoo Mars 5 Ultra", printHours: "", printMinutes: "", serviceHours: "", serviceMinutes: "", packageName: "", channelName: settings.channels[0]?.name || "Pix", price: "", linkedOrder: "", notes: "" }; }
function PieceWizard({ settings, onClose, onSave }: { settings: GlobalSettings; onClose: () => void; onSave: () => void }) {
  const [step, setStep] = useState(1); const [form, setForm] = useState<WizardForm>(() => { try { return { ...wizardDefaults(settings), ...JSON.parse(localStorage.getItem("edition-geek-piece-draft") || "{}") }; } catch { return wizardDefaults(settings); } });
  useEffect(() => { localStorage.setItem("edition-geek-piece-draft", JSON.stringify(form)); }, [form]);
  const update = (key: keyof WizardForm, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const similar = readProductHistory(settings).filter((item) => item.type === form.type && (item.category === form.category || item.complexity === form.complexity)).slice(0, 4);
  const printTime = parseBr(form.printHours) + parseBr(form.printMinutes) / 60; const manualTime = parseBr(form.serviceHours) + parseBr(form.serviceMinutes) / 60; const laborRate = activeLaborRate(settings); const indirectRate = activeIndirectRate(settings); const channel = settings.channels.find((item) => item.name === form.channelName) || settings.channels[0]; const packageItem = settings.packages.find((item) => item.name === form.packageName); const material = form.type === "FDM" ? parseBr(form.grams) / 1000 * parseBr(form.filamentKg) : parseBr(form.volumeMl) / 1000 * parseBr(form.resinLiter) * (1 + settings.resinLoss / 100); const machine = form.type === "FDM" ? printTime * settings.fdmMachineRate + printTime * settings.fdmPower * settings.fdmKwh : printTime * settings.resinPower * settings.resinKwh + printTime * (settings.resinPurchase / settings.resinLife); const total = material + machine + manualTime * laborRate + manualTime * indirectRate + (packageItem?.cost || 0); const denominator = 1 - pricingMarginFraction(settings.defaultMargin) - (channel?.commission || 0) / 100 - settings.salesTax / 100; const recommended = denominator > 0 ? total / denominator : 0; const price = parseBr(form.price) || recommended; const profit = price - total - price * ((channel?.commission || 0) / 100) - (channel?.fixedFee || 0);
  const save = () => { const now = new Date().toLocaleString("pt-BR"); if (form.type === "FDM") { const old: FdmHistoryItem[] = JSON.parse(localStorage.getItem("edition-geek-fdm-history") || "[]"); const next: FdmHistoryItem = { ...emptyFdmForm(), name: form.name, category: form.category, complexity: form.complexity, status: form.status, filamentKg: parseBr(form.filamentKg), materialGrams: parseBr(form.grams), printHours: Math.floor(printTime), printMinutes: Math.round((printTime % 1) * 60), design: formatHours(manualTime), packageName: form.packageName, channelName: form.channelName, adjustedPrice: price, notes: `${form.linkedOrder ? `Pedido vinculado: ${form.linkedOrder}. ` : ""}${form.notes}`, id: `wizard-${Date.now()}`, savedAt: now, costs: { fabrication: material + machine, service: manualTime * laborRate, components: packageItem?.cost || 0, indirect: manualTime * indirectRate, total, suggested: recommended, adjusted: price } }; localStorage.setItem("edition-geek-fdm-history", JSON.stringify([next, ...old])); } else { const old: ResinHistoryItem[] = JSON.parse(localStorage.getItem("edition-geek-resin-history") || "[]"); const next: ResinHistoryItem = { ...emptyResinForm(), name: form.name, category: form.category, complexity: form.complexity, status: form.status, printer: form.printer, resinLiter: parseBr(form.resinLiter), volumeMl: parseBr(form.volumeMl), printHours: Math.floor(printTime), printMinutes: Math.round((printTime % 1) * 60), cleaning: formatHours(manualTime), packageName: form.packageName, channelName: form.channelName, adjustedPrice: price, notes: `${form.linkedOrder ? `Pedido vinculado: ${form.linkedOrder}. ` : ""}${form.notes}`, id: `wizard-${Date.now()}`, savedAt: now, costs: { printing: material + machine, labor: manualTime * laborRate, consumables: 0, components: packageItem?.cost || 0, indirect: manualTime * indirectRate, total, suggested: recommended, adjusted: price } }; localStorage.setItem("edition-geek-resin-history", JSON.stringify([next, ...old])); } localStorage.removeItem("edition-geek-piece-draft"); onSave(); };
  const canContinue = step === 1 ? form.name.trim().length > 0 : true;
  return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal piece-wizard" onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">NOVA PEÇA · ETAPA {step} DE 6</p><h2>Cadastre uma nova peça</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div><div className="wizard-progress"><i style={{ width: `${step / 6 * 100}%` }} /></div><div className="wizard-step-labels"><span className={step >= 1 ? "active" : ""}>Identificação</span><span className={step >= 2 ? "active" : ""}>Impressão</span><span className={step >= 3 ? "active" : ""}>Mão de obra</span><span className={step >= 4 ? "active" : ""}>Componentes</span><span className={step >= 5 ? "active" : ""}>Venda</span><span className={step >= 6 ? "active" : ""}>Resumo</span></div>
    {step === 1 && <div className="wizard-content"><div className="wizard-type-toggle"><button className={form.type === "FDM" ? "selected" : ""} onClick={() => update("type", "FDM")}>FDM · Filamento</button><button className={form.type === "Resina + Pintura" ? "selected" : ""} onClick={() => update("type", "Resina + Pintura")}>Resina + Pintura</button></div><div className="form-grid two"><WizardField label="Nome do produto / projeto" value={form.name} onChange={(value) => update("name", value)} placeholder="Ex: Cubo Infinito" /><WizardSelect label="Categoria" value={form.category} options={form.type === "FDM" ? ["Decoração", "Colecionável", "Chaveiro", "Pokébola", "Espada Anime", "Estátua", "Outro"] : ["Estátua", "Colecionável", "Decoração", "Busto", "Anime", "Games", "Personalizado", "Outro"]} onChange={(value) => update("category", value)} /><WizardSelect label="Complexidade estimada" value={form.complexity} options={["Simples", "Intermediária", "Complexa-Premium"]} onChange={(value) => update("complexity", value)} /><WizardSelect label="Status inicial" value={form.status} options={form.type === "FDM" ? ["Em produção", "Pronto para venda", "Vendido", "Cancelado"] : ["Em produção", "Pronto", "Vendido", "Cancelado"]} onChange={(value) => update("status", value)} /></div>{form.name && <div className="wizard-similar"><b>Produtos similares no histórico</b>{similar.length ? similar.map((item) => <span key={item.id}>{item.name} · {money(item.totalCost)} · {item.workHours.toFixed(1)}h</span>) : <small>Nenhum similar encontrado ainda.</small>}</div>}</div>}
    {step === 2 && <div className="wizard-content"><h3>Dados de impressão {form.type === "FDM" ? "FDM" : "Resina"}</h3><div className="form-grid two">{form.type === "FDM" ? <><WizardField label="Custo do filamento (R$/kg)" value={form.filamentKg} onChange={(value) => update("filamentKg", value)} placeholder="110,00" /><WizardField label="Material gasto (g)" value={form.grams} onChange={(value) => update("grams", value)} placeholder="0" /></> : <><WizardSelect label="Impressora usada" value={form.printer} options={["Elegoo Mars 5 Ultra", "Elegoo Saturn 4 Ultra"]} onChange={(value) => update("printer", value)} /><WizardField label="Custo da resina (R$/L)" value={form.resinLiter} onChange={(value) => update("resinLiter", value)} placeholder="150,00" /><WizardField label="Volume de resina (ml)" value={form.volumeMl} onChange={(value) => update("volumeMl", value)} placeholder="0" /></>}<WizardField label="Horas de impressão" value={form.printHours} onChange={(value) => update("printHours", value)} placeholder="0" /><WizardField label="Minutos de impressão" value={form.printMinutes} onChange={(value) => update("printMinutes", value)} placeholder="0" /></div><div className="wizard-live-total"><span>Custo de impressão estimado</span><strong>{money(material + machine)}</strong></div></div>}
    {step === 3 && <div className="wizard-content"><h3>{form.type === "FDM" ? "Tempo de serviço do Fábio" : "Pós-processamento e pintura"}</h3><p className="fdm-helper">Somente tempo efetivamente trabalhado, sem impressão automática ou secagem.</p><div className="form-grid two"><WizardField label={form.type === "FDM" ? "Projeto + fatiamento (horas)" : "Limpeza + preparação (horas)"} value={form.serviceHours} onChange={(value) => update("serviceHours", value)} placeholder="0" /><WizardField label={form.type === "FDM" ? "Montagem / acabamento (minutos)" : "Pintura + acabamento (minutos)"} value={form.serviceMinutes} onChange={(value) => update("serviceMinutes", value)} placeholder="0" /></div><div className="wizard-live-total"><span>Total de horas manuais</span><strong>{manualTime.toFixed(2)} h · custo {money(manualTime * laborRate)}</strong></div></div>}
    {step === 4 && <div className="wizard-content"><h3>Componentes e embalagem</h3><div className="form-grid two"><WizardSelect label="Embalagem" value={form.packageName} options={["", ...settings.packages.map((item) => item.name)]} onChange={(value) => update("packageName", value)} /><WizardField label="Pedido vinculado (opcional)" value={form.linkedOrder} onChange={(value) => update("linkedOrder", value)} placeholder="Ex: #2048" /></div><div className="wizard-live-total"><span>Custo de componentes selecionados</span><strong>{money(packageItem?.cost || 0)}</strong></div><p className="wizard-hint">Os demais componentes específicos podem ser detalhados na calculadora completa depois de salvar o rascunho.</p></div>}
    {step === 5 && <div className="wizard-content"><h3>Canal e preço de venda</h3><div className="form-grid two"><WizardSelect label="Canal de venda" value={form.channelName} options={settings.channels.map((item) => item.name)} onChange={(value) => update("channelName", value)} /><WizardField label="Preço que vai praticar (R$)" value={form.price} onChange={(value) => update("price", value)} placeholder={recommended.toFixed(2).replace(".", ",")} /><WizardField label="Observações" value={form.notes} onChange={(value) => update("notes", value)} placeholder="Notas da negociação..." /></div><div className="wizard-price-grid"><div><small>Preço mínimo</small><strong>{money(total / (1 - (channel?.commission || 0) / 100 - settings.salesTax / 100))}</strong></div><div><small>Preço recomendado</small><strong>{money(recommended)}</strong></div><div><small>Preço para eventos</small><strong>{money(recommended * (1 + settings.eventAdditional / 100))}</strong></div></div></div>}
    {step === 6 && <div className="wizard-content"><h3>Resumo da nova peça</h3><div className="wizard-summary-grid"><span>Produto<strong>{form.name}</strong></span><span>Tipo<strong>{form.type}</strong></span><span>Impressão<strong>{printTime.toFixed(2)} h</strong></span><span>Trabalho Fábio<strong>{manualTime.toFixed(2)} h</strong></span><span>Custo total<strong>{money(total)}</strong></span><span>Preço praticado<strong>{money(price)}</strong></span><span>Lucro estimado<strong>{money(profit)}</strong></span><span>Pedido vinculado<strong>{form.linkedOrder || "Nenhum"}</strong></span></div>{price < total && <div className="fdm-alerts"><div>⚠️ O preço praticado está abaixo do custo total.</div></div>}<p className="wizard-hint">O rascunho será removido e a ficha será gravada no histórico da calculadora {form.type}.</p></div>}
    <div className="modal-actions"><button className="secondary-button" onClick={step === 1 ? onClose : () => setStep((value) => value - 1)}>{step === 1 ? "Cancelar" : "Voltar"}</button>{step < 6 ? <button className="primary-button" disabled={!canContinue} onClick={() => setStep((value) => value + 1)}>Continuar <ArrowRight size={14} /></button> : <button className="primary-button" onClick={save}><Save size={14} /> Salvar no histórico</button>}</div></div></div>;
}
function WizardField({ label, value, onChange, placeholder }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) { return <label className="field fdm-field"><span>{label}</span><input className="yellow-input" value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} /></label>; }
function WizardSelect({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { const finalOptions = label === "Status inicial" && options.includes("Pronto para venda") && !options.includes("Orçamento") ? ["Em produção", "Orçamento", ...options.filter((option) => option !== "Em produção")] : options; return <label className="field fdm-field"><span>{label}</span><select className="yellow-input" value={value} onChange={(event) => onChange(event.target.value)}>{finalOptions.map((option) => <option key={option} value={option}>{option || "Nenhuma"}</option>)}</select></label>; }
function QuickOrderModal({ onClose, onSave }: { onClose: () => void; onSave: () => void }) { return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal large-modal" onMouseDown={(e) => e.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">PEDIDO RÁPIDO</p><h2>Novo pedido</h2></div><button className="close-button" onClick={onClose} aria-label="Fechar"><X size={18} /></button></div><div className="form-grid two"><Field label="Cliente" placeholder="Selecione um cliente" select /><Field label="Prazo de entrega (dias)" placeholder="7" /></div><div className="panel modal-section"><SectionTitle title="Custos Gerais da Venda" icon={Boxes} /><div className="form-grid two"><Field label="Atendimento / envio" placeholder="Nenhum" select /><Field label="Tempo (min)" placeholder="0" /></div><button className="secondary-button"><Plus size={14} /> Adicionar embalagem</button></div><div className="result-summary"><b>Resultado do Pedido</b><Metric label="Custo dos produtos" value="R$ 0,00" /><Metric label="Valor total" value="R$ 0,00" danger /></div><div className="modal-actions"><button className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button" onClick={onSave}>Salvar pedido</button></div></div></div>; }
